"""Editorial source for the interactive course. R is the single computational engine."""
from pathlib import Path
import json,re,textwrap,subprocess
ROOT=Path(__file__).resolve().parents[2]
ACT=[]
def num(key,label,value,lo,hi,step=1,help=''):
 return dict(key=key,label=label,type='number',value=value,min=lo,max=hi,step=step,help=help)
def choice(key,label,options,value=None,help=''):
 return dict(key=key,label=label,type='select',options=[dict(value=k,label=v) for k,v in options],value=value or options[0][0],help=help)
N=lambda v=60: num('n','Numero di osservazioni',v,12,300,6)
B=lambda: num('B','Repliche del procedimento',200,40,1000,20,'Aumentare le repliche riduce l’incertezza Monte Carlo; la numerosità del campione rimane invariata.')
noise=lambda: num('noise','Deviazione standard dell’errore',1,.1,4,.1)
seed=num('seed','Seme casuale',17,1,99999,1,'A parità di ambiente R, il seme permette di ricostruire la simulazione.')
def add(module,section,slug,title,goal,action,conclusion,formula,controls,code,limits='',presets=None):
 m=json.loads((ROOT/'moduli'/module/'modulo.json').read_text())
 s=m['sections'][section-1]; end=m['sections'][section]['page'] if section<len(m['sections']) else m['pages']+1
 slides=[x for x in m['slides'] if s['page']<=x['page']<end and x.get('body')]
 prose=[x['body'] for x in slides[:2]]
 a=dict(id=module.lower()+'-'+slug,module=module,section=section,sectionTitle=s['title'],page=s['page'],title=title,goal=goal,action=action,conclusion=conclusion,formula=formula,controls=controls+[seed],prose=prose,limits=limits,presets=presets or [],source='R/experiments/'+module.lower()+'-'+slug+'.R',code=textwrap.dedent(code).strip())
 ACT.append(a)
# Each experiment returns data, plots, metrics and an interpretation from the current parameters.
add('T00',1,'programma','Dal dato alla trasformazione','Seguire gli oggetti prodotti da una sequenza di istruzioni.','Modifica il fattore di conversione; confronta il vettore iniziale, quello trasformato e la media.','Una trasformazione elementare permette di ricostruire il passaggio fra dato e risultato.',r'y_i=a x_i,\quad \bar y=a\bar x',[num('a','Fattore di conversione',1000,.1,2000,.1)],'''
x <- c(.12,.18,.21,.16,.24,.19); y <- p$a*x
data <- data.frame(campione=seq_along(x),x=x,y=y)
plots <- list(point_plot(data,'campione','y','Valori trasformati','Campione','Valore trasformato'))
metrics <- metric('Media iniziale'=f(mean(x)),'Media trasformata'=f(mean(y)))
''')
add('T00',2,'tipi','Tipi, vettori e selezioni','Esaminare una selezione logica e la sua applicazione a un vettore.','Sposta la soglia e osserva quali misure entrano nella sintesi.','La media riguarda soltanto le osservazioni selezionate; la dimensione del sottoinsieme va dichiarata.',r'I_i=\mathbf{1}(x_i>c),\quad \bar x_I=\frac{\sum I_i x_i}{\sum I_i}',[num('cut','Soglia di selezione',5,0,10,.5)],'''
x<-c(2,7,4,9,1,6,3,8,5,10);data<-data.frame(x=seq_along(x),y=x,stato=ifelse(x>p$cut,'Selezionato','Escluso'))
plots<-list(point_plot(data,title='Selezione logica',xl='Indice',yl='Misura',group='stato')+geom_hline(yintercept=p$cut,linetype=2))
metrics<-metric('Selezionati'=sum(x>p$cut),'Media selezionata'=if(any(x>p$cut))f(mean(x[x>p$cut]))else'Non definita')
''')
add('T00',3,'lettura','Dalla tabella alla sintesi','Confrontare aggregazioni ottenute da misure appartenenti a gruppi.','Modifica la differenza fra gruppi e ricostruisci i risultati mediante aggregate().','Una tabella analitica conserva le informazioni necessarie a distinguere le unità di osservazione.',r'\bar x_g=n_g^{-1}\sum_{i\in g}x_i',[num('delta','Differenza fra litologie',2,0,8,.5)],'''
data<-data.frame(gruppo=rep(c('A','B'),each=20),valore=rnorm(40,rep(c(5,5+p$delta),each=20)))
plots<-list(ggplot(data,aes(gruppo,valore,fill=gruppo))+geom_boxplot(width=.5)+scale_fill_manual(values=col_geo)+labs(title='Misure e appartenenza',x='Litologia',y='Valore'))
metrics<-metric('Media A'=f(mean(data$valore[data$gruppo=='A'])),'Media B'=f(mean(data$valore[data$gruppo=='B'])))
''')
add('T00',4,'errori','Diagnosi di un calcolo incompleto','Individuare l’effetto di un valore mancante sulla sintesi.','Introduci un valore mancante e confronta media diretta e media dei dati disponibili.','L’eliminazione dei mancanti cambia l’insieme delle osservazioni utilizzate.',r'n_{\rm obs}=\sum_i\mathbf{1}(x_i\ne\mathrm{NA})',[choice('missing','Valore mancante',[('no','Assente'),('yes','Presente')])],'''
x<-c(3,4,5,6,12);if(p$missing=='yes')x[5]<-NA
data<-data.frame(indice=1:5,valore=x)
plots<-list(point_plot(data,'indice','valore','Osservazioni disponibili','Indice','Valore'))
metrics<-metric('Osservazioni disponibili'=sum(!is.na(x)),'mean(x)'=as.character(mean(x)),'mean(x, na.rm=TRUE)'=f(mean(x,na.rm=TRUE)))
''')
add('T00',5,'sessione','Sessione pulita e dipendenze','Riconoscere un risultato che dipende da un oggetto precedente.','Cambia il valore ereditato; confrontalo con la funzione che dichiara esplicitamente il proprio argomento.','Il risultato riproducibile dipende da dati e parametri dichiarati.',r'y=f(x;\theta)',[num('hidden','Fattore ereditato dalla sessione',2,1,10),num('explicit','Fattore dichiarato',3,1,10)],'''
x<-1:6;data<-rbind(data.frame(x=x,y=x*p$hidden,procedura='Oggetto ereditato'),data.frame(x=x,y=x*p$explicit,procedura='Parametro esplicito'))
plots<-list(line_plot(data,title='Dipendenza dal parametro',xl='Ingresso',yl='Risultato',group='procedura'))
metrics<-metric('Scarto massimo'=max(abs(x*p$hidden-x*p$explicit)))
''')
add('T00',6,'prestazioni','Ciclo e calcolo vettoriale','Verificare l’equivalenza numerica di due procedimenti.','Aumenta la lunghezza del vettore e confronta i risultati del ciclo con quelli vettoriali.','L’equivalenza dei valori precede il confronto delle prestazioni, che dipendono dall’ambiente.',r'\sum_{i=1}^n x_i^2=\lVert x\rVert^2',[num('n','Lunghezza del vettore',100,10,3000,10)],'''
x<-rnorm(p$n);loop<-numeric(p$n);for(i in seq_along(x))loop[i]<-x[i]^2;vector<-x^2
data<-data.frame(x=loop,y=vector)
plots<-list(point_plot(data,title='Confronto elemento per elemento',xl='Ciclo',yl='Operazione vettoriale')+geom_abline(slope=1,intercept=0,linetype=2))
metrics<-metric('Scarto massimo'=max(abs(loop-vector)),'Elementi verificati'=length(x))
''')
add('T00',7,'persistenza','Ricostruire un risultato salvato','Separare oggetto in memoria e dato persistente.','Scegli la precisione di salvataggio e misura la perdita introdotta dall’arrotondamento.','La persistenza comprende formato, precisione e contesto del dato.',r'e_i=x_i-\operatorname{round}(x_i,d)',[num('digits','Cifre decimali salvate',2,0,8)],'''
x<-runif(30);file<-tempfile(fileext='.csv');write.csv(data.frame(valore=round(x,p$digits)),file,row.names=FALSE);saved<-read.csv(file)$valore;unlink(file);data<-data.frame(x=seq_along(x),y=x-saved)
plots<-list(point_plot(data,title='Errore introdotto dal salvataggio',xl='Osservazione',yl='Originale − salvato'))
metrics<-metric('Errore massimo'=f(max(abs(x-saved)),7),'Errore quadratico medio'=f(mean((x-saved)^2),7))
''')
add('T00',8,'confronto','Confrontare implementazioni','Valutare una tolleranza numerica dichiarata.','Varia l’ordine di grandezza e la tolleranza; osserva il confronto fra due espressioni algebricamente equivalenti.','L’identità algebrica può produrre risultati numerici differenti in aritmetica finita.',r'(a+b)-a\quad\hbox{e}\quad b',[num('exponent','Esponente di a = 10^k',16,1,18),num('tolerance','Tolleranza assoluta',.01,0,1,.01)],'''
a<-10^p$exponent;b<-1;u<-(a+b)-a;data<-data.frame(gruppo=c('(a+b)−a','b'),valore=c(u,b))
plots<-list(bar_plot(data,title='Cancellazione numerica'))
metrics<-metric('Scarto assoluto'=abs(u-b),'Entro tolleranza'=abs(u-b)<=p$tolerance)
''')
add('M01',1,'estimando','Definire la quantità di interesse','Distinguere media delle misure e media delle unità geologiche.','Aumenta le misure nella prima stazione e confronta i due estimandi.','Il peso attribuito a ogni unità determina la quantità sintetizzata.',r'\bar x_{\rm misure}=\frac{\sum_g n_g\bar x_g}{\sum_g n_g},\quad \bar x_{\rm stazioni}=G^{-1}\sum_g\bar x_g',[num('rep','Misure nella stazione A',20,2,100,2)],'''
data<-data.frame(stazione=rep(c('A','B','C'),c(p$rep,10,10)),valore=c(rnorm(p$rep,3,.4),rnorm(10,7,.4),rnorm(10,10,.4)))
plots<-list(ggplot(data,aes(stazione,valore,fill=stazione))+geom_boxplot()+scale_fill_manual(values=col_geo)+labs(x='Stazione',y='Concentrazione [mg/L]',title='Supporto della sintesi'))
metrics<-metric('Media delle misure'=f(mean(data$valore)),'Media delle stazioni'=f(mean(tapply(data$valore,data$stazione,mean))))
''')
add('M01',2,'gerarchia','Misure replicate e unità indipendenti','Separare variabilità fra stazioni e variabilità entro stazione.','Varia la componente fra stazioni, mantenendo costante il numero di misure.','Le repliche tecniche condividono la componente della propria stazione.',r'X_{gj}=\mu+U_g+\varepsilon_{gj},\quad \rho=\frac{\tau^2}{\tau^2+\sigma^2}',[num('tau','Deviazione standard fra stazioni',2,0,5,.25)],'''
g<-rep(1:8,each=8);u<-rnorm(8,0,p$tau);data<-data.frame(stazione=factor(g),valore=10+u[g]+rnorm(64))
plots<-list(ggplot(data,aes(stazione,valore,colour=stazione))+geom_point(position=position_jitter(width=.12,seed=p$seed),size=2.5)+guides(colour='none')+labs(title='Gerarchia del campione',x='Stazione',y='Misura'))
metrics<-metric('Stazioni'=8,'Misure'=64,'Correlazione intraclasse teorica'=f(p$tau^2/(p$tau^2+1)))
''')
add('M01',3,'unita','Unità e analisi dimensionale','Verificare l’effetto delle unità sul valore numerico.','Converti la medesima lunghezza e confronta media, dispersione e coefficiente di variazione.','Le quantità dimensionali cambiano con l’unità; i rapporti adimensionali coerenti rimangono invariati.',r'\mu_{aX}=a\mu_X,\quad \sigma_{aX}=|a|\sigma_X',[choice('unit','Unità di lunghezza',[('1','Metri'),('100','Centimetri'),('1000','Millimetri')])],'''
a<-as.numeric(p$unit);x<-rnorm(60,2,.2);data<-data.frame(x=seq_along(x),y=a*x)
plots<-list(point_plot(data,title='Una grandezza, unità differenti',xl='Campione',yl='Lunghezza nell’unità scelta'))
metrics<-metric('Media'=f(mean(a*x)),'Deviazione standard'=f(sd(a*x)),'CV'=f(sd(a*x)/mean(a*x)))
''')
add('M01',4,'disegno','Disegnare una campagna di misura','Valutare la copertura di una raccolta su un territorio sintetico.','Confronta punti casuali, griglia regolare e punti raccolti lungo una strada.','La distribuzione geografica del campione determina quali porzioni del territorio sono osservate.',r'\widehat\mu=n^{-1}\sum_i z(s_i)',[choice('design','Disegno',[('random','Casuale'),('grid','Griglia'),('road','Lungo la strada')]),N()],'''
grid<-expand.grid(x=seq(0,1,length.out=35),y=seq(0,1,length.out=35));grid$z<-10+5*grid$x+3*grid$y
xy<-if(p$design=='grid'){k<-ceiling(sqrt(p$n));as.matrix(expand.grid(seq(0,1,length.out=k),seq(0,1,length.out=k))[round(seq(1,k*k,length.out=p$n)),])}else cbind(runif(p$n),if(p$design=='road')runif(p$n,0,.1)else runif(p$n))
data<-data.frame(x=xy[,1],y=xy[,2]);data$z<-10+5*data$x+3*data$y
plots<-list(map_plot(grid,title='Campo e localizzazione dei prelievi')+geom_point(data=data,aes(x,y),inherit.aes=FALSE,colour='#132532',size=2))
metrics<-metric('Media del campo'=14,'Media campionaria'=f(mean(data$z)),'Scarto'=f(mean(data$z)-14))
''')
add('M01',5,'misura','Bias e rumore di misura','Separare spostamento sistematico e dispersione casuale.','Modifica separatamente bias e deviazione standard dell’errore.','La ripetizione attenua la variabilità della media senza rimuovere il bias strumentale.',r'Y=x_0+b+\varepsilon,\quad E(Y)-x_0=b',[num('bias','Bias strumentale',1,-3,3,.25),noise(),N()],'''
x0<-10;y<-x0+p$bias+rnorm(p$n,sd=p$noise);data<-data.frame(misura=y)
plots<-list(hist_plot(y,'Misure ripetute','Misura')+geom_vline(xintercept=x0,colour=col_geo[2],linewidth=1))
metrics<-metric('Valore di riferimento'=x0,'Media misurata'=f(mean(y)),'Scarto della media'=f(mean(y)-x0),'Errore standard teorico'=f(p$noise/sqrt(p$n)))
''')
add('M01',6,'confondimento','Associazione aggregata e condizionata','Osservare il ruolo di una variabile comune a risposta e predittore.','Aumenta la separazione fra gruppi e confronta la pendenza aggregata con quella aggiustata.','L’associazione dipende dalla composizione del campione e dalle variabili incluse nel modello.',r'Y=\beta_0+\beta_1 X+\beta_2 G+\varepsilon',[num('shift','Separazione fra gruppi',3,0,6,.25)],'''
g<-rep(0:1,each=50);x<-rnorm(100)+g*p$shift;y<-.6*x-4*g+rnorm(100,sd=.5);data<-data.frame(x,y,gruppo=factor(g))
a<-lm(y~x);b<-lm(y~x+g)
plots<-list(point_plot(data,title='Associazione e composizione',group='gruppo')+geom_abline(intercept=coef(a)[1],slope=coef(a)[2],linetype=2))
metrics<-metric('Pendenza aggregata'=f(coef(a)[2]),'Pendenza aggiustata'=f(coef(b)[2]))
''')
add('M01',7,'conclusione','Sensibilità della conclusione','Documentare come una scelta analitica modifica una sintesi.','Varia la soglia di esclusione e confronta numerosità e media risultante.','La regola di esclusione fa parte del procedimento e deve accompagnarne la conclusione.',r'\widehat\mu(c)=\frac{\sum x_i\mathbf1(x_i\le c)}{\sum\mathbf1(x_i\le c)}',[num('cut','Massimo ammesso',8,3,15,.5)],'''
x<-c(rnorm(80,5,1),12,14);keep<-x<=p$cut;data<-data.frame(x=seq_along(x),y=x,stato=ifelse(keep,'Incluso','Escluso'))
plots<-list(point_plot(data,title='Scelta analitica dichiarata',xl='Osservazione',yl='Valore',group='stato')+geom_hline(yintercept=p$cut,linetype=2))
metrics<-metric('Osservazioni incluse'=sum(keep),'Media completa'=f(mean(x)),'Media dopo esclusione'=if(any(keep))f(mean(x[keep]))else'Non definita: selezione vuota')
''')
add('M01',8,'censura','Limite di rilevabilità e disponibilità','Distinguere valore osservato, mancante e censurato.','Aumenta il limite di rilevabilità e confronta diverse sostituzioni convenzionali.','La sostituzione dei censurati incorpora un’ipotesi e modifica la distribuzione.',r'Y_i=\begin{cases}X_i&X_i\ge L\\{<L}&X_i<L\end{cases}',[num('limit','Limite di rilevabilità',2,.1,5,.1)],'''
x<-rlnorm(150,.7,.6);data<-data.frame(x=x,metodo='Valori latenti');q<-x<p$limit
plots<-list(hist_plot(x,'Distribuzione latente e censura','Concentrazione [mg/L]')+geom_vline(xintercept=p$limit,colour=col_geo[2],linewidth=1))
metrics<-metric('Censurati'=sum(q),'Media latente'=f(mean(x)),'Sostituzione L/2'=f(mean(ifelse(q,p$limit/2,x))),'Solo rilevati'=f(mean(x[!q])))
''')
add('M01',9,'primo-r','Dal campione al riepilogo R','Leggere insieme tabella, grafico e statistiche descrittive.','Cambia la numerosità e verifica i risultati con mean(), sd() e summary().','Il riepilogo numerico conserva le unità e la definizione della popolazione simulata.',r'\bar x=\frac1n\sum_i x_i,\quad s^2=\frac{\sum_i(x_i-\bar x)^2}{n-1}',[N()],'''
x<-rnorm(p$n,10,2);data<-data.frame(campione=seq_along(x),valore=x);plots<-list(hist_plot(x,'Il primo campione','Valore'))
metrics<-metric('n'=length(x),'Media'=f(mean(x)),'Deviazione standard'=f(sd(x)),'Mediana'=f(median(x)))
''')
add('M01',10,'confronto-disegni','Confrontare campagne ripetute','Valutare bias e dispersione di due disegni campionari.','Aumenta n e osserva la distribuzione delle medie con e senza selezione territoriale.','La precisione intorno a un valore distorto può aumentare mentre l’errore rispetto al bersaglio persiste.',r'\operatorname{MSE}(\hat\theta)=\operatorname{Var}(\hat\theta)+\operatorname{Bias}(\hat\theta)^2',[N(),B()],'''
a<-replicate(p$B,mean(runif(p$n,0,1)));b<-replicate(p$B,mean(runif(p$n,0,.4)));data<-data.frame(valore=c(a,b),disegno=rep(c('Casuale','Settore accessibile'),each=p$B))
plots<-list(ggplot(data,aes(valore,fill=disegno))+geom_histogram(bins=25,alpha=.65,position='identity')+scale_fill_manual(values=col_geo)+geom_vline(xintercept=.5,linetype=2)+labs(title='Distribuzioni campionarie',x='Media della coordinata',y='Repliche'))
metrics<-metric('MSE casuale'=f(mean((a-.5)^2)),'MSE selezionato'=f(mean((b-.5)^2)))
''')
add('M02',1,'progetto','Oggetti espliciti e stato dell’analisi','Ricostruire le dipendenze di un risultato.','Modifica il parametro di calibrazione e osserva quali valori devono essere ricalcolati.','Un progetto riproducibile rende espliciti i parametri da cui dipendono i risultati.',r'z_i=a x_i+b',[num('a','Pendenza di calibrazione',1,.5,2,.1),num('b','Intercetta',0,-3,3,.25)],'''
x<-seq(1,10);data<-data.frame(x=x,y=p$a*x+p$b)
plots<-list(point_plot(data,title='Trasformazione dichiarata',xl='Misura grezza',yl='Misura calibrata')+geom_abline(intercept=p$b,slope=p$a,colour=col_geo[2]))
metrics<-metric('Parametro a'=p$a,'Parametro b'=p$b,'Media calibrata'=mean(data$y))
''')
add('M02',2,'selezioni','Selezioni logiche e tipi','Combinare due condizioni di selezione.','Scegli un intervallo; verifica riga per riga quali misure soddisfano entrambe le condizioni.','Le operazioni logiche definiscono il campione analitico.',r'I_i=\mathbf1(a\le x_i\le b)',[num('lo','Limite inferiore',3,0,9),num('hi','Limite superiore',8,1,10)],'''
x<-seq(0,10,.5);a<-min(p$lo,p$hi);b<-max(p$lo,p$hi);data<-data.frame(x=seq_along(x),y=x,stato=ifelse(x>=a&x<=b,'Incluso','Escluso'))
plots<-list(point_plot(data,title='Intersezione di condizioni',xl='Riga',yl='Valore',group='stato'));metrics<-metric('Inclusi'=sum(x>=a&x<=b),'Esclusi'=sum(x<a|x>b))
''')
add('M02',3,'importazione','Importare numeri con convenzioni differenti','Diagnosticare errori prodotti da separatori decimali incompatibili.','Cambia la convenzione di lettura e confronta stringhe, valori convertiti e mancanti.','La conversione deve rispettare la convenzione del file di origine.',r'n_{\rm validi}=\sum_i\mathbf1(\mathrm{conversione}(s_i)\ne\mathrm{NA})',[choice('decimal','Separatore riconosciuto',[('comma','Virgola'),('point','Punto')])],'''
raw<-c('1,2','2,4','3,1','4,8','ND');x<-suppressWarnings(as.numeric(if(p$decimal=='comma')sub(',','.',raw,fixed=TRUE)else raw))
data<-data.frame(riga=seq_along(raw),testo=raw,valore=x)
plots<-list(bar_plot(data.frame(gruppo=c('Validi','Non convertiti'),valore=c(sum(!is.na(x)),sum(is.na(x)))),title='Esito dell’importazione',yl='Righe'))
metrics<-metric('Righe valide'=sum(!is.na(x)),'Media disponibile'=if(any(!is.na(x)))f(mean(x,na.rm=TRUE))else'Non definita')
''')
add('M02',4,'aggregazioni','Aggregazione e pesi delle osservazioni','Confrontare media complessiva e media delle medie.','Modifica la numerosità di un gruppo e verifica quando le due sintesi coincidono.','I pesi dell’aggregazione dipendono dall’unità cui si riferisce la domanda.',r'\bar x=\frac{\sum_g n_g\bar x_g}{\sum_g n_g}',[num('nA','Misure nel gruppo A',50,5,100,5)],'''
data<-data.frame(gruppo=rep(c('A','B'),c(p$nA,10)),valore=c(rnorm(p$nA,3),rnorm(10,8)))
a<-aggregate(valore~gruppo,data,mean);plots<-list(bar_plot(a,title='Medie dei gruppi'))
metrics<-metric('Media delle osservazioni'=f(mean(data$valore)),'Media delle medie'=f(mean(a$valore)))
''')
add('M02',5,'join','Collegare tabelle senza moltiplicare le misure','Verificare la cardinalità di un collegamento mediante una chiave.','Introduci una seconda riga di metadati per la stazione B; confronta le tabelle prima e dopo il join.','Una chiave duplicata può replicare le osservazioni e modificarne il peso.',r'n_{\rm join}(k)=n_A(k)n_B(k)',[choice('duplicate','Chiave B nei metadati',[('no','Univoca'),('yes','Duplicata')])],'''
a<-data.frame(stazione=c('A','B','C'),misura=c(2,5,9));b<-data.frame(stazione=c('A','B','C'),quota=c(100,200,300));if(p$duplicate=='yes')b<-rbind(b,data.frame(stazione='B',quota=210))
data<-merge(a,b,by='stazione',all.x=TRUE)
plots<-list(bar_plot(data.frame(gruppo=names(table(data$stazione)),valore=as.numeric(table(data$stazione))),title='Righe dopo il collegamento',yl='Molteplicità'))
metrics<-metric('Righe iniziali'=nrow(a),'Righe finali'=nrow(data),'Media iniziale'=mean(a$misura),'Media dopo join'=f(mean(data$misura)))
''')
add('M02',6,'mancanti','Meccanismo di indisponibilità','Confrontare dati mancanti casualmente e mancanti associati al valore.','Aumenta l’indisponibilità e confronta la media disponibile con quella dei dati completi.','La quantità di dati mancanti e il meccanismo di indisponibilità hanno conseguenze differenti.',r'E(X\mid R=1)\quad\hbox{e}\quad E(X)',[choice('mechanism','Meccanismo',[('random','Casuale'),('high','Valori elevati meno disponibili')]),num('rate','Frazione indicativa indisponibile',.3,0,.8,.1)],'''
x<-rlnorm(200,1,.5);miss<-if(p$mechanism=='random')runif(200)<p$rate else rank(x)>200*(1-p$rate)
data<-data.frame(x=seq_along(x),y=x,stato=ifelse(miss,'Indisponibile','Disponibile'))
plots<-list(point_plot(data,title='Meccanismo di indisponibilità',xl='Osservazione',yl='Concentrazione',group='stato'));metrics<-metric('Mancanti'=sum(miss),'Media completa'=f(mean(x)),'Media disponibile'=f(mean(x[!miss])))
''')
add('M02',7,'controlli','Controlli di plausibilità fisica','Distinguere validità sintattica e coerenza fisica.','Introduci temperature fuori dominio e osserva quali righe vengono segnalate.','Il controllo esplicito conserva l’informazione sull’anomalia e sulla decisione adottata.',r'v_i=\mathbf1(L\le x_i\le U)',[num('bad','Temperatura sospetta [°C]',250,-100,500,10)],'''
x<-c(rnorm(29,15,3),p$bad);valid<-x>=-50&x<=60;data<-data.frame(x=1:30,y=x,stato=ifelse(valid,'Nel dominio','Da verificare'))
plots<-list(point_plot(data,title='Registro delle anomalie',xl='Riga',yl='Temperatura [°C]',group='stato')+geom_hline(yintercept=c(-50,60),linetype=2));metrics<-metric('Righe segnalate'=sum(!valid),'Media senza modifica'=f(mean(x)))
''')
add('M02',8,'composizione','Chiusura di una composizione','Osservare l’effetto del vincolo di somma costante.','Aumenta una componente prima della normalizzazione e segui le percentuali delle altre.','La variazione di una percentuale dipende anche dal denominatore comune.',r'c_j=100\frac{x_j}{\sum_k x_k}',[num('a','Quantità della componente A',40,1,100,1)],'''
x<-c(A=p$a,B=35,C=25);data<-data.frame(gruppo=names(x),valore=100*x/sum(x));plots<-list(bar_plot(data,title='Composizione normalizzata',yl='Percentuale'))
metrics<-metric('Somma'=sum(data$valore),'Rapporto B/C'=f(x[2]/x[3]),'Percentuale B'=f(data$valore[2]))
''')
add('M02',9,'funzioni','Contratti di validità di una funzione','Verificare precondizioni prima di eseguire un calcolo.','Imposta una deviazione standard nulla o positiva; osserva quando la standardizzazione è definita.','Una funzione deve riconoscere input che rendono il risultato matematicamente indefinito.',r'z_i=(x_i-\bar x)/s,\quad s>0',[num('spread','Ampiezza delle differenze',1,0,3,.25)],'''
x<-5+p$spread*c(-2,-1,0,1,2);ok<-sd(x)>0;z<-if(ok)as.vector(scale(x))else rep(NA_real_,5);data<-data.frame(x=1:5,y=x,z=z)
plots<-list(point_plot(data,title='Input della funzione',xl='Indice',yl='Valore'));metrics<-metric('Deviazione standard'=f(sd(x)),'Contratto s > 0'=ok,'Media standardizzata'=if(ok)f(mean(z))else'Non definita')
''')
add('M02',10,'tabella','Verificare una tabella analitica','Controllare righe, chiavi e unità prima dell’analisi.','Attiva un duplicato e una conversione incoerente; segui i controlli che li individuano.','La consegna comprende la tabella e il resoconto delle verifiche.',r'n_{\rm chiavi}=|\operatorname{unique}(ID)|',[choice('duplicate','Duplica una chiave',[('no','No'),('yes','Sì')]),choice('unit','Unità dell’ultima misura',[('ok','Coerente'),('wrong','Millimetri letti come metri')])],'''
data<-data.frame(id=1:8,lunghezza=c(1.1,1.3,1.2,1.5,1.4,1.1,1.6,1.2));if(p$duplicate=='yes')data$id[8]<-7;if(p$unit=='wrong')data$lunghezza[8]<-1200
plots<-list(point_plot(data,'id','lunghezza','Controllo della tabella','Identificativo','Lunghezza dichiarata [m]'))
metrics<-metric('Chiavi duplicate'=sum(duplicated(data$id)),'Valori fuori dominio'=sum(data$lunghezza>10),'Righe'=nrow(data))
''')
# Descriptive statistics: distinct operations on the same declared measurement scale.
add('M03',1,'supporto','Supporto della rappresentazione','Confrontare misure puntuali e medie di stazione.','Cambia la dispersione entro stazione e confronta le due rappresentazioni.','Il grafico deve rendere riconoscibile l’unità che ciascun simbolo rappresenta.',r'\bar x_g=n_g^{-1}\sum_jx_{gj}',[noise()],'''
g<-rep(1:6,each=8);data<-data.frame(gruppo=factor(g),valore=rep(seq(2,7),each=8)+rnorm(48,sd=p$noise));a<-aggregate(valore~gruppo,data,mean)
plots<-list(ggplot(data,aes(gruppo,valore))+geom_point(position=position_jitter(width=.12,seed=p$seed),colour=col_geo[1],size=2)+geom_point(data=a,shape=18,size=5,colour=col_geo[2])+labs(title='Misure e medie di stazione',x='Stazione',y='Valore'));metrics<-metric('Misure'=48,'Medie di stazione'=6)
''')
add('M03',2,'denominatori','Frequenze, denominatori e pesi','Confrontare conteggi e proporzioni fra gruppi di dimensione diversa.','Modifica il denominatore del secondo gruppo mantenendo i conteggi degli eventi.','Un conteggio acquista significato comparativo quando è accompagnato dal denominatore pertinente.',r'\widehat p_g=k_g/n_g',[num('nB','Osservazioni nel gruppo B',100,20,200,10),choice('scale','Rappresentazione',[('count','Conteggi'),('rate','Proporzioni')])],'''
data<-data.frame(gruppo=c('A','B'),eventi=c(10,20),n=c(50,p$nB));data$valore<-if(p$scale=='count')data$eventi else data$eventi/data$n
plots<-list(bar_plot(data,title='Denominatori del confronto',yl=if(p$scale=='count')'Eventi'else'Proporzione'));metrics<-metric('Proporzione A'=.2,'Proporzione B'=f(20/p$nB))
''')
add('M03',3,'posizione','Media e mediana sotto contaminazione','Valutare la sensibilità delle misure di posizione.','Sposta l’osservazione estrema lasciando ferme le altre.','La media e la mediana rispondono in modo differente a una perturbazione localizzata.',r'\bar x=n^{-1}\sum x_i,\quad\widetilde x=Q_{0.5}',[num('outlier','Valore dell’ultima osservazione',15,0,100)],'''
x<-c(rnorm(29,10,1),p$outlier);data<-data.frame(x=1:30,y=x);plots<-list(point_plot(data,title='Una sola osservazione modificata',xl='Indice',yl='Valore')+geom_hline(yintercept=mean(x),colour=col_geo[2])+geom_hline(yintercept=median(x),colour=col_geo[3],linetype=2));metrics<-metric('Media'=f(mean(x)),'Mediana'=f(median(x)))
''')
add('M03',4,'quantili','Dispersione e intervallo interquartile','Confrontare dispersione quadratica e dispersione centrale.','Aumenta l’ampiezza della distribuzione e osserva deviazione standard e IQR.','I quantili delimitano frazioni della distribuzione empirica; la deviazione standard pesa le distanze quadratiche.',r'\operatorname{IQR}=Q_{0.75}-Q_{0.25}',[noise(),N()],'''
x<-rnorm(p$n,10,p$noise);data<-data.frame(gruppo='Campione',valore=x);plots<-list(ggplot(data,aes(gruppo,valore))+geom_boxplot(fill=col_geo[1],width=.4)+labs(title='Quantili e dispersione',x=NULL,y='Misura'));metrics<-metric('Deviazione standard'=f(sd(x)),'IQR'=f(IQR(x)),'Q25'=f(quantile(x,.25)),'Q75'=f(quantile(x,.75)))
''')
add('M03',5,'smoothing','Istogramma e stima di densità','Distinguere struttura dei dati e scelte di rappresentazione.','Modifica numero di classi e banda della densità senza generare nuovi dati.','La regolarità della curva dipende dal parametro di smoothing.',r'\widehat f_h(x)=\frac1{nh}\sum_iK\!\left(\frac{x-x_i}{h}\right)',[num('bins','Classi dell’istogramma',18,4,50),num('bw','Banda della densità',.5,.1,2,.1)],'''
x<-c(rnorm(100,-1,.6),rnorm(80,1.4,.7));data<-data.frame(valore=x)
plots<-list(ggplot(data,aes(valore))+geom_histogram(aes(y=after_stat(density)),bins=p$bins,fill=col_geo[1],alpha=.6,colour='#F5F6F3')+geom_density(bw=p$bw,colour=col_geo[2],linewidth=1.2)+labs(title='Le stesse osservazioni',x='Valore',y='Densità'));metrics<-metric('Osservazioni'=length(x),'Banda'=p$bw,'Classi'=p$bins)
''')
add('M03',6,'gruppi','Confronti fra distribuzioni','Separare differenze di posizione e dispersione.','Varia la differenza delle medie e la dispersione del secondo gruppo.','La sovrapposizione delle distribuzioni e lo spostamento della media descrivono proprietà differenti.',r'\Delta=E(Y_B)-E(Y_A)',[num('delta','Differenza delle medie',1,-3,3,.25),num('ratio','Rapporto delle deviazioni standard',1,.25,3,.25)],'''
data<-data.frame(gruppo=rep(c('A','B'),each=70),valore=c(rnorm(70),rnorm(70,p$delta,p$ratio)))
plots<-list(ggplot(data,aes(valore,colour=gruppo))+geom_density(linewidth=1.1)+scale_colour_manual(values=col_geo)+labs(title='Posizione e dispersione',x='Misura',y='Densità'));metrics<-metric('Differenza osservata'=f(diff(tapply(data$valore,data$gruppo,mean))),'Rapporto SD osservato'=f(sd(data$valore[71:140])/sd(data$valore[1:70])))
''')
add('M03',7,'relazioni','Relazione lineare e non lineare','Confrontare forma del legame e coefficiente di correlazione.','Passa da una relazione lineare a una curva mantenendo simile il rumore.','Una correlazione prossima a zero può accompagnare una relazione non lineare definita.',r'r=\frac{\sum_i(x_i-\bar x)(y_i-\bar y)}{\sqrt{\sum_i(x_i-\bar x)^2\sum_i(y_i-\bar y)^2}}',[choice('shape','Forma',[('line','Lineare'),('curve','Quadratica')]),noise()],'''
x<-seq(-2,2,length.out=100);y<-if(p$shape=='line')x else x^2;y<-y+rnorm(100,sd=p$noise);data<-data.frame(x,y)
plots<-list(point_plot(data,title='Forma dell’associazione'));metrics<-metric('Pearson r'=f(cor(x,y)),'Spearman rho'=f(cor(x,y,method='spearman')))
''')
add('M03',8,'mappa','Posizione e rappresentazione spaziale','Riconoscere una struttura geografica nascosta in un riepilogo.','Varia il gradiente territoriale e confronta mappa e istogramma.','La distribuzione marginale omette l’ordinamento geografico delle misure.',r'z(s)=\mu+\beta x(s)+\varepsilon(s)',[num('gradient','Gradiente verso Est',4,0,8,.5)],'''
data<-expand.grid(x=1:20,y=1:20);data$z<-10+p$gradient*data$x/20+rnorm(nrow(data),sd=.3)
plots<-list(map_plot(data,title='Distribuzione nel territorio'),hist_plot(data$z,'Distribuzione marginale','Valore'));metrics<-metric('Media'=f(mean(data$z)),'Deviazione standard'=f(sd(data$z)))
''')
add('M03',9,'scale','Scale lineari e logaritmiche','Esaminare un processo moltiplicativo su due scale.','Cambia la dispersione logaritmica e confronta dati originali e logaritmi.','Il logaritmo trasforma rapporti in differenze e modifica la quantità sintetizzata.',r'\log(xy)=\log x+\log y',[num('sdlog','Deviazione standard logaritmica',.7,.1,1.5,.1)],'''
x<-rlnorm(200,1,p$sdlog);data<-data.frame(originale=x,logaritmo=log(x));plots<-list(hist_plot(x,'Scala originale','Concentrazione'),hist_plot(log(x),'Scala logaritmica','Log concentrazione'));metrics<-metric('Media aritmetica'=f(mean(x)),'Media geometrica'=f(exp(mean(log(x)))))
''')
add('M04',1,'eventi','Eventi e frequenze relative','Confrontare probabilità dichiarata e frequenza simulata.','Modifica la probabilità dell’evento e aumenta il numero di prove.','La frequenza relativa varia da campione a campione intorno alla probabilità del modello.',r'\widehat p_n=\frac1n\sum_{i=1}^n I_i',[num('prob','Probabilità dell’evento',.3,.05,.95,.05),num('n','Numero di prove',200,20,2000,20)],'''
x<-rbinom(p$n,1,p$prob);data<-data.frame(x=1:p$n,y=cumsum(x)/(1:p$n));plots<-list(line_plot(data,title='Frequenza cumulativa',xl='Prove',yl='Frequenza relativa')+geom_hline(yintercept=p$prob,colour=col_geo[2],linetype=2)+coord_cartesian(ylim=c(0,1)));metrics<-metric('Probabilità teorica'=p$prob,'Frequenza finale'=f(mean(x)))
''')
add('M04',2,'condizionamento','Probabilità condizionata','Distinguere probabilità marginale e probabilità entro un gruppo.','Cambia la composizione dei gruppi mantenendo fisse le probabilità condizionate.','La probabilità marginale combina le probabilità condizionate con i pesi dei gruppi.',r'P(A)=P(A\mid B)P(B)+P(A\mid B^c)P(B^c)',[num('prior','P(B)',.4,.05,.95,.05),num('pa','P(A | B)',.8,.05,.95,.05),num('pb','P(A | non B)',.2,.05,.95,.05)],'''
pa<-p$pa*p$prior+p$pb*(1-p$prior);post<-p$pa*p$prior/pa;data<-data.frame(gruppo=c('P(A|B)','P(A|non B)','P(A)','P(B|A)'),valore=c(p$pa,p$pb,pa,post));plots<-list(bar_plot(data,title='Marginali e condizionate',yl='Probabilità')+coord_cartesian(ylim=c(0,1)));metrics<-metric('P(A)'=f(pa),'P(B|A)'=f(post),'Indipendenza A e B'=abs(p$pa-p$pb)<1e-10)
''')
add('M04',3,'distribuzione','Distribuzione cumulativa e quantili','Collegare densità, area e probabilità cumulativa.','Sposta la soglia e osserva l’area cumulata sotto la densità.','La probabilità di un intervallo è un’area, mentre l’altezza della densità dipende anche dall’unità.',r'F(c)=\int_{-\infty}^c f(x)\,dx',[num('cut','Soglia standardizzata',1,-3,3,.1)],'''
data<-data.frame(x=seq(-4,4,length.out=401));data$y<-dnorm(data$x);plots<-list(line_plot(data,title='Densità normale standard',xl='z',yl='Densità')+geom_area(data=subset(data,x<=p$cut),fill=col_geo[1],alpha=.35)+geom_vline(xintercept=p$cut,linetype=2));metrics<-metric('F(soglia)'=f(pnorm(p$cut)),'Probabilità di superamento'=f(pnorm(p$cut,lower.tail=FALSE)))
''')
add('M04',4,'binomiale','Bernoulli e distribuzione binomiale','Collegare prove elementari e conteggio dei successi.','Varia numero di prove e probabilità; confronta distribuzione teorica e conteggi simulati.','La binomiale assume prove indipendenti con probabilità comune.',r'P(K=k)=\binom nk p^k(1-p)^{n-k}',[num('n','Prove per replica',20,2,60,2),num('prob','Probabilità per prova',.3,.05,.95,.05)],'''
k<-0:p$n;data<-data.frame(k=k,probabilita=dbinom(k,p$n,p$prob));sim<-rbinom(400,p$n,p$prob);emp<-tabulate(sim+1,nbins=p$n+1)/400
plots<-list(ggplot(data,aes(k,probabilita))+geom_col(fill=col_geo[1],width=.7)+geom_point(aes(y=emp),colour=col_geo[2],size=2)+labs(title='Teoria e 400 repliche',x='Successi',y='Probabilità / frequenza'))
metrics<-metric('Media teorica'=p$n*p$prob,'Varianza teorica'=p$n*p$prob*(1-p$prob),'Media simulata'=f(mean(sim)))
''')
add('M04',5,'poisson','Conteggi ed esposizione','Distinguere tasso e numero atteso di eventi.','Aumenta l’esposizione mantenendo costante il tasso.','Il parametro del conteggio cresce con l’esposizione prevista dal modello.',r'K\sim\operatorname{Poisson}(\lambda E),\quad E(K)/E=\lambda',[num('rate','Tasso per unità di esposizione',2,.2,5,.2),num('exposure','Esposizione',3,1,10)],'''
mu<-p$rate*p$exposure;k<-0:qpois(.999,mu);data<-data.frame(x=k,y=dpois(k,mu));plots<-list(ggplot(data,aes(x,y))+geom_col(fill=col_geo[1])+labs(title='Conteggi attesi all’esposizione scelta',x='Eventi',y='Probabilità'));metrics<-metric('Conteggio atteso'=mu,'Tasso'=p$rate,'Deviazione standard del conteggio'=f(sqrt(mu)))
''')
add('M04',6,'normale','Standardizzazione e quantili normali','Collegare unità originali e unità standardizzate.','Cambia media, deviazione standard e probabilità cumulata del quantile.','La standardizzazione conserva l’ordinamento e rende esplicita la distanza dalla media in unità di deviazione standard.',r'z=(x-\mu)/\sigma,\quad q_u=\mu+\sigma\Phi^{-1}(u)',[num('mu','Media',10,0,20),num('sd','Deviazione standard',2,.5,5,.5),num('q','Probabilità cumulata',.95,.05,.95,.05)],'''
x<-seq(p$mu-4*p$sd,p$mu+4*p$sd,length.out=300);data<-data.frame(x=x,y=dnorm(x,p$mu,p$sd));q<-qnorm(p$q,p$mu,p$sd);plots<-list(line_plot(data,title='Quantile sulla scala originale',xl='Valore',yl='Densità')+geom_vline(xintercept=q,colour=col_geo[2],linewidth=1));metrics<-metric('Quantile originale'=f(q),'Quantile standardizzato'=f(qnorm(p$q)))
''')
add('M04',7,'moltiplicazione','Variabilità moltiplicativa','Esaminare un prodotto di fattori positivi.','Varia la dispersione logaritmica e confronta mediana, media e coda destra.','La simmetria nella scala logaritmica si accompagna ad asimmetria nella scala originale.',r'X=e^Z,\quad Z\sim N(\mu,\sigma^2),\quad E(X)=e^{\mu+\sigma^2/2}',[num('sdlog','Deviazione standard di log(X)',.6,.1,1.5,.1)],'''
x<-rlnorm(500,0,p$sdlog);data<-data.frame(valore=x);plots<-list(hist_plot(x,'Processo moltiplicativo','X'));metrics<-metric('Mediana teorica'=1,'Media teorica'=f(exp(p$sdlog^2/2)),'Media simulata'=f(mean(x)))
''')
add('M04',8,'monte-carlo','Precisione della simulazione Monte Carlo','Separare incertezza numerica e variabilità del fenomeno.','Aumenta il numero di repliche senza modificare la probabilità dell’evento.','L’errore Monte Carlo dipende dal numero di repliche utilizzate nella stima numerica.',r'\operatorname{SE}_{MC}(\widehat p)=\sqrt{p(1-p)/B}',[B(),num('prob','Probabilità dell’evento',.1,.01,.5,.01)],'''
x<-rbinom(p$B,1,p$prob);k<-1:p$B;data<-data.frame(x=k,y=cumsum(x)/k);plots<-list(line_plot(data,title='Stima Monte Carlo',xl='Repliche B',yl='Frequenza')+geom_hline(yintercept=p$prob,linetype=2,colour=col_geo[2]));metrics<-metric('Stima'=f(mean(x)),'Errore standard Monte Carlo teorico'=f(sqrt(p$prob*(1-p$prob)/p$B)))
''')
add('M04',9,'propagazione','Propagare incertezze correlate','Valutare l’incertezza di un rapporto fra misure positive.','Varia la correlazione degli ingressi e confronta simulazione e approssimazione differenziale.','La covarianza degli ingressi contribuisce alla variabilità della grandezza derivata.',r'\operatorname{Var}(f(X))\simeq\nabla f^\top\Sigma\nabla f',[num('rho','Correlazione fra i logaritmi degli ingressi',0,-.8,.8,.1),num('cv','SD dei logaritmi degli ingressi',.1,.02,.3,.02)],'''
z<-matrix(rnorm(4000),ncol=2);u<-z[,1];v<-p$rho*u+sqrt(1-p$rho^2)*z[,2];x<-exp(log(10)+p$cv*u);y<-exp(log(5)+p$cv*v);ratio<-x/y;data<-data.frame(x=x,y=y,rapporto=ratio);plots<-list(hist_plot(ratio,'Rapporto di misure correlate','X/Y'));metrics<-metric('SD simulata'=f(sd(ratio)),'SD differenziale sui log'=f(2*p$cv*sqrt(2*(1-p$rho))),'SD esatta del rapporto'=f(2*sqrt(expm1(2*p$cv^2*(1-p$rho))*exp(2*p$cv^2*(1-p$rho)))))
''')
# M05: iid and dependent sampling are handled explicitly.
add('M05',2,'estimandi','Campionare per misure o per stazioni','Confrontare bersagli definiti da pesi differenti.','Modifica il numero di misure nella stazione a concentrazione maggiore.','La media delle misure e quella delle stazioni rispondono a domande differenti.',r'\theta_w=\sum_gw_g\mu_g,\quad\sum_gw_g=1',[num('nHigh','Misure nella stazione elevata',40,5,100,5)],'''
data<-data.frame(stazione=rep(c('A','B','C'),c(10,10,p$nHigh)),valore=c(rnorm(10,5),rnorm(10,6),rnorm(p$nHigh,12)));a<-aggregate(valore~stazione,data,mean);plots<-list(ggplot(data,aes(stazione,valore,fill=stazione))+geom_boxplot()+scale_fill_manual(values=col_geo)+labs(title='Pesi delle unità campionarie',x='Stazione',y='Concentrazione'));metrics<-metric('Media misure'=f(mean(data$valore)),'Media stazioni'=f(mean(a$valore)))
''')
add('M05',3,'selezione','Precisione e bias di selezione','Osservare l’effetto della selezione su campagne ripetute.','Aumenta n e confronta selezione casuale e preferenza per valori bassi.','Un campione numeroso può produrre stime precise intorno a un bersaglio distorto.',r'\operatorname{MSE}=\operatorname{Var}+\operatorname{Bias}^2',[N(),B(),num('bias','Spostamento dovuto alla selezione',1,0,3,.25)],'''
a<-rnorm(p$B,10,2/sqrt(p$n));b<-rnorm(p$B,10-p$bias,2/sqrt(p$n));data<-data.frame(valore=c(a,b),disegno=rep(c('Casuale','Selezionato'),each=p$B));plots<-list(ggplot(data,aes(valore,fill=disegno))+geom_histogram(bins=25,alpha=.6,position='identity')+scale_fill_manual(values=col_geo)+geom_vline(xintercept=10,linetype=2)+labs(title='Medie in campagne ripetute',x='Stima',y='Repliche'));metrics<-metric('Bias teorico selezionato'=-p$bias,'SD teorica'=f(2/sqrt(p$n)),'MSE selezionato'=f(mean((b-10)^2)))
''',limits='Il modello rappresenta la selezione mediante uno spostamento dichiarato della distribuzione osservata; non simula un algoritmo di inclusione individuale.')
add('M05',4,'distribuzioni','Distribuzione campionaria della media','Distinguere dati individuali e statistiche campionarie.','Scegli una popolazione asimmetrica e aumenta la dimensione di ogni campione.','La distribuzione delle medie dipende dalla popolazione e dalla numerosità di ciascun campione.',r'E(\bar X)=\mu,\quad\operatorname{Var}(\bar X)=\sigma^2/n',[N(),B(),choice('population','Popolazione',[('normal','Normale'),('exp','Esponenziale')])],'''
means<-replicate(p$B,mean(if(p$population=='normal')rnorm(p$n,1,1)else rexp(p$n)));data<-data.frame(media=means);plots<-list(hist_plot(means,'Distribuzione delle medie','Media campionaria')+geom_vline(xintercept=1,linetype=2));metrics<-metric('Media delle medie'=f(mean(means)),'SD empirica'=f(sd(means)),'SE teorico'=f(1/sqrt(p$n)))
''')
add('M05',5,'dipendenza','Errore standard e dipendenza','Quantificare il contributo delle covarianze alla precisione della media.','Mantieni n costante e aumenta la correlazione intraclasse.','Misure che condividono una componente comune apportano meno informazione di misure indipendenti.',r'\operatorname{Var}(\bar X)=\frac{\sigma^2}{n}\{1+(n-1)\rho\}',[N(),B(),num('rho','Correlazione comune',.2,0,.8,.05)],'''
means<-replicate(p$B,{u<-rnorm(1);mean(sqrt(p$rho)*u+sqrt(1-p$rho)*rnorm(p$n))});actual<-sqrt((1+(p$n-1)*p$rho)/p$n);data<-data.frame(media=means);plots<-list(hist_plot(means,'Medie di campioni correlati','Media')+geom_vline(xintercept=c(-1.96,1.96)/sqrt(p$n),linetype=2,colour=col_geo[2]));metrics<-metric('SE assumendo indipendenza'=f(1/sqrt(p$n)),'SE corretto teorico'=f(actual),'SD delle repliche'=f(sd(means)),'n effettivo'=f(p$n/(1+(p$n-1)*p$rho)))
''',limits='Modello gaussiano equicorrelato con varianza marginale unitaria e correlazione non negativa. Le linee tratteggiate delimitano ±1,96/√n attorno alla media vera.')
add('M05',6,'intervalli','Copertura degli intervalli di confidenza','Osservare la copertura frequentista in campioni ripetuti.','Confronta campioni indipendenti e correlati utilizzando il medesimo intervallo t.','La copertura si riferisce alla frequenza con cui il procedimento include il parametro nelle repliche.',r'I_b=\bar x_b\pm t_{n-1,1-\alpha/2}\frac{s_b}{\sqrt n}',[N(30),B(),num('rho','Correlazione comune',0,0,.6,.05),num('level','Livello nominale',.95,.8,.99,.01)],'''
z<-t(replicate(p$B,{u<-rnorm(1);x<-10+sqrt(p$rho)*u+sqrt(1-p$rho)*rnorm(p$n);c(mean(x),sd(x)/sqrt(p$n))}));q<-qt((1+p$level)/2,p$n-1);data<-data.frame(replica=1:p$B,media=z[,1],inferiore=z[,1]-q*z[,2],superiore=z[,1]+q*z[,2]);data$copre<-data$inferiore<=10&data$superiore>=10
shown<-head(data,80);plots<-list(ggplot(shown,aes(media,replica,colour=copre))+geom_segment(aes(x=inferiore,xend=superiore,yend=replica),linewidth=.7)+geom_point(size=1.5)+geom_vline(xintercept=10,linetype=2)+scale_colour_manual(values=c('FALSE'=col_geo[2],'TRUE'=col_geo[1]),labels=c('Non include μ','Include μ'))+labs(title='Intervalli: prime 80 repliche',x='Media e intervallo',y='Replica'))
metrics<-metric('Copertura osservata'=f(mean(data$copre)),'Livello nominale'=p$level,'Repliche'=p$B,'MC SE copertura'=f(sqrt(mean(data$copre)*(1-mean(data$copre))/p$B)))
''')
add('M05',7,'bootstrap','Ricampionare il campione osservato','Costruire una distribuzione bootstrap e un intervallo percentile.','Conserva il campione e aumenta B; poi cambia seme per osservare la variabilità tra campioni.','Il bootstrap approssima la distribuzione dello stimatore mediante ricampionamento dal campione osservato.',r'\widehat F_n=\frac1n\sum_i\delta_{x_i},\quad X_i^*\sim\widehat F_n',[N(30),B()],'''
x<-rlnorm(p$n,0,.6);boot<-replicate(p$B,mean(sample(x,replace=TRUE)));data<-data.frame(replica=seq_along(boot),media=boot);ci<-quantile(boot,c(.025,.975));plots<-list(hist_plot(boot,'Distribuzione bootstrap della media','Media ricampionata')+geom_vline(xintercept=ci,linetype=2,colour=col_geo[2]));metrics<-metric('Media osservata'=f(mean(x)),'SE bootstrap'=f(sd(boot)),'Percentile 2,5%'=f(ci[1]),'Percentile 97,5%'=f(ci[2]))
''')
add('M05',8,'ricampionamento','Ricampionamento per stazioni','Confrontare bootstrap delle misure e delle unità indipendenti.','Aumenta la componente comune alla stazione; confronta la dispersione dei due ricampionamenti.','Il disegno di ricampionamento deve conservare la struttura di dipendenza pertinente.',r'X_{gj}=\mu+U_g+\varepsilon_{gj}',[num('tau','SD fra stazioni',2,0,5,.25),B()],'''
G<-12;m<-6;u<-rnorm(G,0,p$tau);x<-matrix(10+rep(u,each=m)+rnorm(G*m),nrow=m);a<-replicate(p$B,mean(sample(as.vector(x),replace=TRUE)));b<-replicate(p$B,mean(x[,sample(1:G,replace=TRUE)]));data<-data.frame(media=c(a,b),metodo=rep(c('Singole misure','Stazioni intere'),each=p$B));plots<-list(ggplot(data,aes(media,colour=metodo))+geom_density(linewidth=1.1)+scale_colour_manual(values=col_geo)+labs(title='Struttura del ricampionamento',x='Media bootstrap',y='Densità'));metrics<-metric('SE singole misure'=f(sd(a)),'SE stazioni'=f(sd(b)),'Unità indipendenti'=G)
''')
add('M05',9,'precisione','Stabilità numerica di un quantile bootstrap','Valutare l’incertezza dovuta al numero finito di ricampionamenti.','Aumenta B mantenendo il campione fisso; confronta il limite superiore in ripetizioni indipendenti del bootstrap.','Un limite bootstrap stimato con poche repliche può oscillare sensibilmente anche a campione invariato.',r'\widehat q_{0.975}^{*(B)}',[B()],'''
x<-rlnorm(30,0,.6);q<-replicate(30,quantile(replicate(p$B,mean(sample(x,replace=TRUE))),.975));data<-data.frame(x=1:30,y=q);plots<-list(point_plot(data,title='Ripetizioni del calcolo bootstrap',xl='Ripetizione del calcolo',yl='Limite superiore 97,5%'));metrics<-metric('Repliche per calcolo'=p$B,'SD dei limiti superiori'=f(sd(q)),'Campione fisso: n'=30)
''')
add('M06',1,'contrasto','Definire un contrasto fra gruppi','Collegare disegno e differenza di interesse.','Modifica la differenza delle popolazioni; osserva l’effetto stimato e la sua incertezza.','Il contrasto e le unità indipendenti precedono la scelta del test.',r'\Delta=\mu_B-\mu_A,\quad\widehat\Delta=\bar y_B-\bar y_A',[num('delta','Differenza delle popolazioni',1,-2,2,.25),N(30)],'''
a<-rnorm(p$n);b<-rnorm(p$n,p$delta);data<-data.frame(gruppo=rep(c('A','B'),each=p$n),valore=c(a,b));tt<-t.test(b,a);plots<-list(ggplot(data,aes(gruppo,valore,fill=gruppo))+geom_boxplot()+scale_fill_manual(values=col_geo)+labs(title='Contrasto fra medie',x='Gruppo',y='Risposta'));metrics<-metric('Differenza stimata'=f(mean(b)-mean(a)),'Limite inferiore'=f(tt$conf.int[1]),'Limite superiore'=f(tt$conf.int[2]))
''')
add('M06',2,'permutazione','Costruire il riferimento di permutazione','Seguire la redistribuzione delle etichette sotto scambiabilità.','Varia l’effetto osservato e il numero di permutazioni; confronta il contrasto con il riferimento.','La validità della permutazione dipende dalla scambiabilità delle unità rispetto alle etichette.',r'p_{MC}=\frac{1+\sum_b\mathbf1(|T_b|\ge|T_{obs}|)}{B+1}',[num('delta','Differenza delle popolazioni',.6,0,2,.2),B()],'''
x<-c(rnorm(20),rnorm(20,p$delta));g<-rep(0:1,each=20);obs<-diff(tapply(x,g,mean));ts<-replicate(p$B,{gp<-sample(g);diff(tapply(x,gp,mean))});data<-data.frame(contrasto=ts);pv<-(1+sum(abs(ts)>=abs(obs)))/(p$B+1);plots<-list(hist_plot(ts,'Etichette permutate','Differenza delle medie')+geom_vline(xintercept=c(-abs(obs),abs(obs)),colour=col_geo[2],linetype=2));metrics<-metric('Contrasto osservato'=f(obs),'p Monte Carlo bilaterale'=f(pv),'Permutazioni'=p$B)
''')
add('M06',3,'pvalue','Leggere il p-value nel riferimento nullo','Collegare statistica osservata e area di coda.','Sposta la statistica t e varia i gradi di libertà.','Il p-value misura una probabilità di risultati almeno altrettanto estremi nel riferimento nullo dichiarato.',r'p=2P(T_\nu\ge|t_{obs}|)',[num('t','Statistica osservata',2,-5,5,.1),num('df','Gradi di libertà',20,2,100)],'''
data<-data.frame(x=seq(-6,6,length.out=601));data$y<-dt(data$x,p$df);data$coda<-abs(data$x)>=abs(p$t);plots<-list(line_plot(data,title='Test bilaterale nel riferimento t',xl='t',yl='Densità')+geom_area(data=subset(data,coda),aes(group=x>0),fill=col_geo[2],alpha=.45)+geom_vline(xintercept=c(-abs(p$t),abs(p$t)),linetype=2));metrics<-metric('p bilaterale'=f(2*pt(-abs(p$t),p$df)),'Gradi di libertà'=p$df)
''')
add('M06',4,'potenza','Potenza, effetto e numerosità','Esaminare la probabilità di rifiuto sotto un’alternativa dichiarata.','Varia effetto e numerosità e osserva la curva di potenza.','La potenza riguarda un procedimento ripetuto rispetto a uno specifico effetto e modello.',r'\pi(\delta)=P_\delta(\text{rifiuto di }H_0)',[N(30),num('delta','Effetto standardizzato',.5,.05,1.5,.05),num('alpha','Livello del test',.05,.01,.1,.01)],'''
ns<-seq(5,300,5);pow<-sapply(ns,function(n)power.t.test(n=n,delta=p$delta,sd=1,sig.level=p$alpha,type='two.sample',alternative='two.sided',strict=TRUE)$power);data<-data.frame(x=ns,y=pow);v<-power.t.test(n=p$n,delta=p$delta,sd=1,sig.level=p$alpha,type='two.sample',strict=TRUE)$power;plots<-list(line_plot(data,title='Potenza del test t bilaterale',xl='Osservazioni per gruppo',yl='Probabilità di rifiuto')+geom_vline(xintercept=p$n,linetype=2)+coord_cartesian(ylim=c(0,1)));metrics<-metric('Potenza alla numerosità scelta'=f(v),'Alfa'=p$alpha)
''',limits='Due gruppi indipendenti, varianza comune unitaria, distribuzione normale e test t bilaterale. La curva non rappresenta automaticamente la potenza del test di Welch in presenza di eteroschedasticità.')
add('M06',5,'welch','Due medie con varianze differenti','Calcolare l’incertezza di un contrasto con il test di Welch.','Aumenta il rapporto fra le deviazioni standard e confronta errore standard e gradi di libertà.','Welch utilizza una stima dell’incertezza che conserva le due varianze campionarie.',r'T=\frac{\bar X_B-\bar X_A}{\sqrt{s_A^2/n_A+s_B^2/n_B}}',[num('ratio','Rapporto delle SD',2,.5,4,.25),N(30)],'''
a<-rnorm(p$n);b<-rnorm(p$n,.5,p$ratio);tt<-t.test(b,a);data<-data.frame(gruppo=rep(c('A','B'),each=p$n),valore=c(a,b));plots<-list(ggplot(data,aes(gruppo,valore,fill=gruppo))+geom_boxplot()+scale_fill_manual(values=col_geo)+labs(title='Varianze separate',x='Gruppo',y='Risposta'));metrics<-metric('Differenza'=f(mean(b)-mean(a)),'SE Welch'=f(sqrt(var(a)/p$n+var(b)/p$n)),'Gradi di libertà'=f(tt$parameter),'p'=f(tt$p.value))
''')
add('M06',6,'appaiati','Confrontare misure appaiate','Separare differenze entro unità e variabilità fra unità.','Aumenta la variabilità dei soggetti; confronta analisi appaiata e analisi indipendente.','L’appaiamento conserva l’identità dell’unità e utilizza la distribuzione delle differenze.',r'D_i=Y_{i,post}-Y_{i,pre},\quad\operatorname{SE}(\bar D)=s_D/\sqrt n',[num('tau','SD fra unità',3,0,6,.5)],'''
u<-rnorm(30,0,p$tau);a<-10+u+rnorm(30);b<-10+u+.6+rnorm(30);data<-data.frame(id=rep(1:30,2),tempo=factor(rep(c('Prima','Dopo'),each=30),levels=c('Prima','Dopo')),valore=c(a,b));plots<-list(ggplot(data,aes(tempo,valore,group=id))+geom_line(alpha=.5,colour=col_geo[1])+geom_point(size=1.8)+labs(title='Identità delle coppie',x='Misura',y='Risposta'));metrics<-metric('Media differenze'=f(mean(b-a)),'SE appaiato'=f(sd(b-a)/sqrt(30)),'SE indipendente'=f(sqrt(var(a)/30+var(b)/30)))
''')
add('M06',7,'ranghi','Ranghi e forma delle distribuzioni','Interpretare un confronto basato sull’ordinamento.','Varia spostamento e dispersione del secondo gruppo; confronta ranghi e mediane.','L’interpretazione come spostamento di posizione richiede assunzioni sulla forma delle distribuzioni.',r'\widehat P(Y>X)=\frac1{n_Xn_Y}\sum_{i,j}\mathbf1(Y_j>X_i)',[num('delta','Spostamento del gruppo B',.5,-2,2,.25),num('ratio','Rapporto delle SD',1,.5,3,.25)],'''
a<-rnorm(35);b<-rnorm(35,p$delta,p$ratio);data<-data.frame(gruppo=rep(c('A','B'),each=35),valore=c(a,b));wt<-wilcox.test(b,a,exact=FALSE);plots<-list(ggplot(data,aes(valore,colour=gruppo))+stat_ecdf(linewidth=1)+scale_colour_manual(values=col_geo)+labs(title='Distribuzioni cumulative empiriche',x='Valore',y='Frazione cumulata'));metrics<-metric('P empirica B > A'=f(mean(outer(b,a,'>'))),'Differenza mediane'=f(median(b)-median(a)),'p Wilcoxon'=f(wt$p.value))
''')
add('M06',8,'categorie','Associazione fra categorie','Confrontare conteggi osservati e attesi sotto indipendenza.','Modifica un conteggio della tabella e osserva residui ed evidenza del test.','Il riferimento chi-quadrato è approssimato; con conteggi attesi piccoli il test esatto offre un confronto pertinente.',r'E_{ij}=\frac{n_{i+}n_{+j}}n,\quad X^2=\sum_{ij}\frac{(O_{ij}-E_{ij})^2}{E_{ij}}',[num('count','Eventi nel gruppo B',25,1,60)],'''
tab<-matrix(c(15,35,p$count,60-p$count),nrow=2,byrow=TRUE);ct<-suppressWarnings(chisq.test(tab,correct=FALSE));data<-as.data.frame(as.table(tab));names(data)<-c('gruppo','esito','conteggio');plots<-list(ggplot(data,aes(gruppo,conteggio,fill=esito))+geom_col(position='dodge')+scale_fill_manual(values=col_geo)+labs(title='Tabella di contingenza',x='Gruppo',y='Conteggio'));metrics<-metric('Chi-quadrato'=f(ct$statistic),'Minimo atteso'=f(min(ct$expected)),'p asintotico'=f(ct$p.value),'p Fisher'=f(fisher.test(tab)$p.value))
''')
add('M06',9,'multipli','Molteplicità dei confronti','Osservare falsi positivi in famiglie di test sotto l’ipotesi nulla.','Aumenta il numero di test e confronta valori grezzi e correzione di Holm.','Il controllo dell’errore della famiglia differisce dal livello del singolo test.',r'P(\text{almeno un falso positivo})=1-(1-\alpha)^m',[num('m','Numero di test indipendenti',20,2,100),num('alpha','Livello',.05,.01,.1,.01)],'''
u<-runif(p$m);adj<-p.adjust(u,'holm');data<-data.frame(x=1:p$m,y=u,corretto=adj);plots<-list(point_plot(data,title='p-value sotto l’ipotesi nulla',xl='Test',yl='p-value')+geom_point(aes(y=corretto),colour=col_geo[2],shape=17,size=2)+geom_hline(yintercept=p$alpha,linetype=2));metrics<-metric('Rifiuti grezzi'=sum(u<p$alpha),'Rifiuti Holm'=sum(adj<p$alpha),'FWER teorica grezza'=f(1-(1-p$alpha)^p$m))
''')
add('M06',10,'relazione','Effetto, intervallo ed evidenza','Ricostruire una conclusione quantitativa completa.','Conserva l’effetto della popolazione e aumenta n; confronta ampiezza dell’intervallo e p-value.','L’interpretazione comprende grandezza dell’effetto, precisione e disegno.',r'\widehat\Delta\pm t_{\nu,0.975}\operatorname{SE}(\widehat\Delta)',[N(30),num('delta','Differenza di interesse',.3,0,1,.1)],'''
a<-rnorm(p$n);b<-rnorm(p$n,p$delta);tt<-t.test(b,a);data<-data.frame(x=mean(b)-mean(a),y=1,lo=tt$conf.int[1],hi=tt$conf.int[2]);plots<-list(point_plot(data,title='Stima e intervallo al 95%',xl='Differenza B − A',yl='Contrasto')+geom_segment(aes(x=lo,xend=hi,yend=y),linewidth=1)+geom_vline(xintercept=0,linetype=2)+scale_y_continuous(breaks=NULL));metrics<-metric('Effetto stimato'=f(data$x),'Ampiezza intervallo'=f(diff(tt$conf.int)),'p Welch'=f(tt$p.value))
''')
add('M07',1,'dominio','Dominio osservato ed estrapolazione','Distinguere previsione entro e oltre il campo osservato.','Sposta la posizione di previsione rispetto al dominio del campione.','La forma del modello assume un ruolo crescente oltre il dominio sostenuto dai dati.',r'\widehat y_0=\widehat\beta_0+\widehat\beta_1x_0',[num('x0','Posizione da prevedere',4,-3,12,.5)],'''
x<-runif(50,0,5);y<-2+x+.12*x^2+rnorm(50,.0,.5);fit<-lm(y~x);data<-data.frame(x,y);pred<-predict(fit,data.frame(x=p$x0),interval='prediction');plots<-list(point_plot(data,title='Campo osservato e previsione')+geom_abline(intercept=coef(fit)[1],slope=coef(fit)[2],colour=col_geo[2])+annotate('point',x=p$x0,y=pred[1],shape=18,size=5,colour=col_geo[3])+expand_limits(x=p$x0));metrics<-metric('Previsione'=f(pred[1]),'Ampiezza intervallo'=f(pred[3]-pred[2]),'Fuori dominio'=p$x0<min(x)||p$x0>max(x))
''')
add('M07',2,'correlazione','Correlazione e restrizione del campo','Osservare l’effetto del dominio dei predittori sulla correlazione.','Restringi il campo delle x mantenendo fissa la pendenza e il rumore.','Il coefficiente di correlazione dipende dalla variabilità del predittore nella popolazione osservata.',r'Y=\alpha+\beta X+\varepsilon',[num('range','Ampiezza del campo di X',4,.5,8,.5),noise()],'''
x<-runif(100,-p$range,p$range);y<-2*x+rnorm(100,sd=p$noise);data<-data.frame(x,y);fit<-lm(y~x);plots<-list(point_plot(data,title='Variabilità del predittore')+geom_abline(intercept=coef(fit)[1],slope=coef(fit)[2],colour=col_geo[2]));metrics<-metric('Pearson r'=f(cor(x,y)),'Pendenza stimata'=f(coef(fit)[2]),'Pendenza generatrice'=2)
''')
add('M07',3,'minimi-quadrati','La geometria dei minimi quadrati','Confrontare una retta proposta con la soluzione che minimizza gli scarti quadratici.','Muovi intercetta e pendenza; osserva segmenti residui e somma dei quadrati.','La soluzione OLS minimizza la somma dei quadrati sul campione dichiarato.',r'(\widehat\beta_0,\widehat\beta_1)=\arg\min_{a,b}\sum_i(y_i-a-bx_i)^2',[num('intercept','Intercetta proposta',1,-3,6,.25),num('slope','Pendenza proposta',1,-1,3,.1)],'''
x<-seq(0,5,length.out=18);y<-1.5+1.2*x+rnorm(18,sd=.7);fit<-lm(y~x);data<-data.frame(x,y,pred=p$intercept+p$slope*x)
plots<-list(point_plot(data,title='Retta proposta e residui')+geom_segment(aes(xend=x,yend=pred),colour=col_geo[2],alpha=.7)+geom_abline(intercept=p$intercept,slope=p$slope,colour=col_geo[2],linewidth=1)+geom_abline(intercept=coef(fit)[1],slope=coef(fit)[2],colour=col_geo[3],linetype=2));metrics<-metric('SSE proposta'=f(sum((y-data$pred)^2)),'SSE minima OLS'=f(sum(resid(fit)^2)),'Intercetta OLS'=f(coef(fit)[1]),'Pendenza OLS'=f(coef(fit)[2]))
''')
add('M07',4,'previsione','Intervallo della media e di una nuova osservazione','Separare incertezza della risposta media e variabilità di un evento futuro.','Varia il rumore e confronta le due bande sullo stesso campione.','L’intervallo di previsione comprende anche la variabilità di una nuova osservazione.',r'\operatorname{SE}_{pred}(x_0)=s\sqrt{1+h_0},\quad\operatorname{SE}_{media}(x_0)=s\sqrt{h_0}',[noise(),N(60)],'''
x<-runif(p$n,0,10);y<-2+.8*x+rnorm(p$n,sd=p$noise);fit<-lm(y~x);grid<-data.frame(x=seq(-2,12,length.out=100));a<-predict(fit,grid,interval='confidence');b<-predict(fit,grid,interval='prediction');data<-data.frame(grid,fit=a[,1],cl=a[,2],cu=a[,3],pl=b[,2],pu=b[,3]);plots<-list(ggplot(data,aes(x,fit))+geom_ribbon(aes(ymin=pl,ymax=pu),fill=col_geo[3],alpha=.2)+geom_ribbon(aes(ymin=cl,ymax=cu),fill=col_geo[1],alpha=.5)+geom_line(colour=col_geo[1])+geom_point(data=data.frame(x,y),aes(x,y),inherit.aes=FALSE,size=1.7)+labs(title='Banda esterna: previsione; interna: media',x='Predittore',y='Risposta'));metrics<-metric('SD residua'=f(summary(fit)$sigma),'R²'=f(summary(fit)$r.squared))
''')
add('M07',5,'influenza','Leva e influenza di un’osservazione','Distinguere distanza nel predittore e influenza sul modello.','Sposta l’ultima osservazione mediante le due coordinate e confronta le rette con e senza quel punto.','L’influenza combina geometria del predittore e scostamento dalla relazione stimata.',r'D_i=\frac{e_i^2}{p\widehat\sigma^2}\frac{h_{ii}}{(1-h_{ii})^2}',[num('xstar','Coordinata X del punto',8,-4,15,.25),num('ystar','Coordinata Y del punto',3,-5,20,.25)],'''
x<-c(seq(0,5,length.out=24),p$xstar);y<-c(1+1.2*x[1:24]+rnorm(24,sd=.5),p$ystar);fit<-lm(y~x);ref<-lm(y[-25]~x[-25]);data<-data.frame(x,y,stato=c(rep('Campione',24),'Punto modificabile'))
plots<-list(point_plot(data,title='Influenza sul modello',group='stato')+geom_abline(intercept=coef(fit)[1],slope=coef(fit)[2],colour=col_geo[2])+geom_abline(intercept=coef(ref)[1],slope=coef(ref)[2],linetype=2,colour=col_geo[1]));metrics<-metric('Leva del punto'=f(hatvalues(fit)[25]),'Distanza di Cook'=f(cooks.distance(fit)[25]),'Pendenza con punto'=f(coef(fit)[2]),'Pendenza senza punto'=f(coef(ref)[2]))
''')
add('M07',6,'interazioni','Predittori multipli e interazione','Osservare una pendenza che dipende dal gruppo.','Modifica il coefficiente di interazione e confronta le rette dei due gruppi.','Il significato di un coefficiente dipende dai termini presenti nel modello e dalla codifica dei predittori.',r'E(Y\mid X,G)=\beta_0+\beta_1X+\beta_2G+\beta_3XG',[num('interaction','Coefficiente dell’interazione',.7,-1.5,1.5,.1)],'''
g<-rep(0:1,each=50);x<-runif(100,0,5);y<-1+.6*x+g+p$interaction*x*g+rnorm(100,sd=.6);data<-data.frame(x,y,gruppo=factor(g));fit<-lm(y~x*g);plots<-list(point_plot(data,title='Pendenze condizionate al gruppo',group='gruppo')+geom_smooth(method='lm',formula=y~x,se=FALSE));metrics<-metric('Interazione stimata'=f(coef(fit)[4]),'Pendenza gruppo 0'=f(coef(fit)[2]),'Pendenza gruppo 1'=f(coef(fit)[2]+coef(fit)[4]))
''')
add('M07',7,'logistica','Dalla risposta binaria alla probabilità','Collegare predittore lineare, probabilità e osservazioni binarie.','Varia intercetta e pendenza; osserva la curva logistica e le frequenze simulate.','Una probabilità prevista descrive la distribuzione della risposta binaria condizionata ai predittori.',r'P(Y=1\mid x)=\frac{1}{1+e^{-(\beta_0+\beta_1x)}}',[num('a','Intercetta logit',0,-3,3,.25),num('b','Pendenza logit',1,-3,3,.25)],'''
x<-seq(-3,3,length.out=150);pr<-plogis(p$a+p$b*x);y<-rbinom(150,1,pr);data<-data.frame(x,y,probabilita=pr);plots<-list(point_plot(data,title='Probabilità e realizzazioni',xl='Predittore',yl='Risposta / probabilità')+geom_line(aes(y=probabilita),colour=col_geo[2],linewidth=1.2));metrics<-metric('Probabilità a x=0'=f(plogis(p$a)),'Odds ratio per unità X'=f(exp(p$b)),'Frequenza simulata'=f(mean(y)))
''')
add('M07',8,'validazione','Complessità e prestazione su nuovi dati','Confrontare errore di adattamento e di previsione.','Aumenta il grado del polinomio sul medesimo campione.','L’errore sul campione di adattamento può diminuire mentre quello su nuove osservazioni aumenta.',r'\operatorname{RMSE}=\sqrt{m^{-1}\sum_{i=1}^{m}(y_i-\widehat y_i)^2}',[num('degree','Grado del polinomio',3,1,10),noise()],'''
x<-seq(-1,1,length.out=24);y<-sin(3*x)+rnorm(24,sd=p$noise);fit<-lm(y~poly(x,p$degree,raw=TRUE));xt<-seq(-1,1,length.out=150);yt<-sin(3*xt)+rnorm(150,sd=p$noise);pr<-predict(fit,data.frame(x=xt));data<-data.frame(x=xt,y=pr,vero=sin(3*xt));plots<-list(line_plot(data,title='Modello adattato e relazione generatrice')+geom_line(aes(y=vero),colour=col_geo[3],linetype=2)+geom_point(data=data.frame(x,y),aes(x,y),inherit.aes=FALSE,colour=col_geo[2],size=2));metrics<-metric('RMSE adattamento'=f(sqrt(mean(resid(fit)^2))),'RMSE nuove osservazioni'=f(sqrt(mean((yt-pr)^2))))
''')
add('M08',1,'standardizzazione','Scale e distanze multivariate','Valutare l’effetto delle unità sulla geometria del campione.','Moltiplica la seconda variabile e confronta distanze grezze e standardizzate.','La standardizzazione definisce il peso relativo delle variabili nella distanza.',r'd_{ij}^2=\sum_k(x_{ik}-x_{jk})^2',[num('scale','Moltiplicatore della seconda variabile',10,1,100),choice('standard','Standardizza',[('no','No'),('yes','Sì')])],'''
x<-matrix(rnorm(120),ncol=2);x[,2]<-x[,2]*p$scale;if(p$standard=='yes')x<-scale(x);data<-data.frame(x=x[,1],y=x[,2]);plots<-list(point_plot(data,title='Geometria delle variabili',xl='Variabile 1',yl='Variabile 2')+coord_equal());metrics<-metric('SD variabile 1'=f(sd(x[,1])),'SD variabile 2'=f(sd(x[,2])),'Distanza punti 1 e 2'=f(sqrt(sum((x[1,]-x[2,])^2))))
''')
add('M08',2,'composizioni','Correlazione indotta dalla chiusura','Esaminare variabili positive prima e dopo la normalizzazione.','Cambia la variabilità della terza componente e confronta le correlazioni.','Il vincolo di somma modifica le relazioni fra le componenti; i rapporti restano una descrizione pertinente.',r'\operatorname{clr}(x_j)=\log x_j-\frac1D\sum_k\log x_k',[num('sd3','SD logaritmica della componente C',.7,.1,2,.1)],'''
x<-cbind(rlnorm(150,0,.6),rlnorm(150,0,.6),rlnorm(150,0,p$sd3));comp<-x/rowSums(x);data<-data.frame(x=comp[,1],y=comp[,2]);plots<-list(point_plot(data,title='Componenti A e B dopo chiusura',xl='Frazione A',yl='Frazione B'));metrics<-metric('Correlazione grezza A/B'=f(cor(x[,1],x[,2])),'Correlazione frazioni A/B'=f(cor(comp[,1],comp[,2])),'SD log(A/B)'=f(sd(log(x[,1]/x[,2]))))
''')
add('M08',3,'pca-geometria','Ruotare un asse e misurare la varianza','Costruire geometricamente la prima componente principale.','Ruota l’asse di proiezione e confronta la varianza proiettata con il massimo della PCA.','La prima componente individua la direzione di massima varianza del campione centrato.',r'v_1=\arg\max_{\lVert v\rVert=1}v^\top Sv',[num('angle','Angolo dell’asse [gradi]',30,-90,90,5)],'''
u<-rnorm(80,0,2);x<-cbind(u+rnorm(80,sd=.3),.7*u+rnorm(80,sd=.6));x<-scale(x,scale=FALSE);a<-p$angle*pi/180;v<-c(cos(a),sin(a));pc<-prcomp(x);score<-as.vector(x%*%v);proj<-score%o%v;data<-data.frame(x=x[,1],y=x[,2],px=proj[,1],py=proj[,2]);plots<-list(point_plot(data,title='Proiezione su un asse',xl='Variabile centrata 1',yl='Variabile centrata 2')+geom_segment(aes(xend=px,yend=py),alpha=.25)+annotate('segment',x=-5*v[1],y=-5*v[2],xend=5*v[1],yend=5*v[2],colour=col_geo[2],linewidth=1)+coord_equal());metrics<-metric('Varianza proiettata'=f(var(score)),'Massima varianza PCA'=f(pc$sdev[1]^2),'Quota proiettata'=f(var(score)/sum(pc$sdev^2)))
''')
add('M08',4,'pca-ricostruzione','Componenti, contributi e ricostruzione','Confrontare dati originali e ricostruzione a rango ridotto.','Varia il numero di componenti conservate e osserva l’errore di ricostruzione.','La varianza spiegata quantifica la geometria del campione nella metrica scelta.',r'\widehat X_k=T_kV_k^\top,\quad\mathrm{quota}_j=\lambda_j/\sum_l\lambda_l',[num('k','Componenti conservate',1,1,3)],'''
z<-rnorm(80);x<-cbind(z+rnorm(80,sd=.3),2*z+rnorm(80,sd=.5),rnorm(80));pc<-prcomp(x,scale.=TRUE);xc<-scale(x);rec<-pc$x[,1:p$k,drop=FALSE]%*%t(pc$rotation[,1:p$k,drop=FALSE]);data<-data.frame(gruppo=paste('PC',1:3),valore=pc$sdev^2/sum(pc$sdev^2));plots<-list(bar_plot(data,title='Varianza spiegata',yl='Frazione'),point_plot(data.frame(x=as.vector(xc),y=as.vector(rec)),title='Ricostruzione standardizzata',xl='Originale',yl='Ricostruito')+geom_abline(slope=1,intercept=0,linetype=2));metrics<-metric('Quota conservata'=f(sum(data$valore[1:p$k])),'RMSE ricostruzione'=f(sqrt(mean((xc-rec)^2))))
''')
add('M08',5,'kmeans','Iterazioni di K-means','Seguire assegnazione ai centroidi e aggiornamento delle posizioni.','Aumenta il numero di iterazioni mantenendo fissi dati e inizializzazione.','K-means riduce una somma di distanze quadratiche rispetto ai centroidi nella metrica scelta.',r'J=\sum_i\lVert x_i-\mu_{c_i}\rVert^2',[num('k','Numero dei gruppi',3,2,5),num('iterations','Iterazioni',1,1,12)],'''
x<-rbind(matrix(rnorm(80),ncol=2),matrix(rnorm(80),ncol=2)+3,matrix(rnorm(80),ncol=2)+rep(c(-3,3),each=40));cent<-x[seq(1,nrow(x),length.out=p$k),,drop=FALSE]
for(it in seq_len(p$iterations)){ds<-sapply(1:p$k,function(j)rowSums((sweep(x,2,cent[j,]))^2));cl<-max.col(-ds,ties.method='first');for(j in 1:p$k)if(any(cl==j))cent[j,]<-colMeans(x[cl==j,,drop=FALSE])}
data<-data.frame(x=x[,1],y=x[,2],gruppo=factor(cl));plots<-list(point_plot(data,title='Assegnazioni e centroidi',group='gruppo')+geom_point(data=data.frame(x=cent[,1],y=cent[,2]),aes(x,y),inherit.aes=FALSE,shape=4,size=6,stroke=2));metrics<-metric('Somma quadratica entro gruppi'=f(sum((x-cent[cl,])^2)),'Iterazioni'=p$iterations)
''')
add('M08',6,'silhouette','Numero dei gruppi e silhouette','Valutare coesione e separazione di una partizione.','Varia k sullo stesso campione e confronta silhouette e somma quadratica.','La silhouette valuta una partizione rispetto a una distanza e non certifica categorie geologiche.',r's_i=\frac{b_i-a_i}{\max(a_i,b_i)}',[num('k','Numero dei gruppi',3,2,6)],'''
x<-rbind(matrix(rnorm(60,0,.6),ncol=2),matrix(rnorm(60,3,.6),ncol=2),cbind(rnorm(30,-2,.6),rnorm(30,3,.6)));km<-kmeans(x,p$k,nstart=10);dd<-as.matrix(dist(x));s<-sapply(1:nrow(x),function(i){same<-which(km$cluster==km$cluster[i]&seq_len(nrow(x))!=i);if(!length(same))return(0);a<-mean(dd[i,same]);b<-min(sapply(setdiff(unique(km$cluster),km$cluster[i]),function(g)mean(dd[i,km$cluster==g])));(b-a)/max(a,b)});data<-data.frame(x=seq_along(s),y=sort(s));plots<-list(line_plot(data,title='Silhouette delle osservazioni ordinate',xl='Osservazione ordinata',yl='Silhouette')+geom_hline(yintercept=0,linetype=2));metrics<-metric('Silhouette media'=f(mean(s)),'Somma quadratica'=f(km$tot.withinss))
''')
add('M08',7,'ward','Gerarchie e criterio di Ward','Esaminare fusioni successive e taglio della gerarchia.','Varia il numero di gruppi ottenuti tagliando il medesimo albero.','Ward.D2 applicato a distanze euclidee collega le fusioni all’incremento della dispersione entro gruppi.',r'\Delta(A,B)=\frac{n_An_B}{n_A+n_B}\lVert\bar x_A-\bar x_B\rVert^2',[num('k','Gruppi al taglio',3,2,6)],'''
x<-rbind(matrix(rnorm(40),ncol=2),matrix(rnorm(40),ncol=2)+3);hc<-hclust(dist(x),method='ward.D2');cl<-cutree(hc,p$k);data<-data.frame(x=x[,1],y=x[,2],gruppo=factor(cl));plots<-list(point_plot(data,title='Partizione ottenuta dalla gerarchia',group='gruppo'),line_plot(data.frame(x=seq_along(hc$height),y=hc$height),title='Altezze delle fusioni',xl='Fusione',yl='Altezza Ward.D2'));metrics<-metric('Gruppi'=p$k,'Ultima altezza'=f(tail(hc$height,1)))
''')
add('M08',8,'robustezza','Sensibilità di una partizione','Valutare la stabilità rispetto a perturbazioni dei dati.','Aumenta il rumore aggiunto e confronta le coppie che rimangono nello stesso gruppo.','La stabilità rispetto a perturbazioni è una proprietà del procedimento e del campione.',r'A_{ij}=\mathbf1(c_i=c_j)',[num('perturb','SD della perturbazione',.3,0,2,.1)],'''
x<-rbind(matrix(rnorm(60,0,.6),ncol=2),matrix(rnorm(60,3,.6),ncol=2));a<-kmeans(x,2,nstart=10)$cluster;xp<-x+matrix(rnorm(length(x),sd=p$perturb),ncol=2);b<-kmeans(xp,2,nstart=10)$cluster;sel<-upper.tri(matrix(0,60,60));agreement<-mean((outer(a,a,'==')==outer(b,b,'=='))[sel]);data<-data.frame(x=xp[,1],y=xp[,2],gruppo=factor(b));plots<-list(point_plot(data,title='Partizione dopo perturbazione',group='gruppo'));metrics<-metric('Accordo delle coappartenenze'=f(agreement),'Coppie confrontate'=sum(sel))
''')
add('M09',1,'calendario','Calendario e osservazioni mancanti','Distinguere distanza temporale e posizione nella tabella.','Aumenta i mesi mancanti e confronta calendario effettivo e indice delle osservazioni disponibili.','L’indice di riga non sostituisce il calendario quando gli intervalli di osservazione sono irregolari.',r'\Delta t_i=t_i-t_{i-1}',[num('missing','Mesi da escludere',8,0,36,2)],'''
t<-1:120;y<-sin(2*pi*t/12)+t/100+rnorm(120,sd=.15);keep<-rep(TRUE,120);if(p$missing>0)keep[sample(2:119,p$missing)]<-FALSE;data<-data.frame(mese=t[keep],valore=y[keep],indice=seq_len(sum(keep)));plots<-list(line_plot(data,'mese','valore','Calendario conservato','Mese','Valore'),line_plot(data,'indice','valore','Tempo compresso dall’indice','Riga disponibile','Valore'));metrics<-metric('Osservazioni'=sum(keep),'Intervallo massimo fra osservazioni'=max(diff(t[keep])))
''')
add('M09',2,'aggregazione','Risoluzione temporale e copertura','Esaminare gli effetti dell’aggregazione di una serie.','Modifica l’ampiezza delle finestre e confronta valori originali e medie aggregate.','L’aggregazione attenua componenti ad alta frequenza e cambia il supporto temporale.',r'\bar x_k=|W_k|^{-1}\sum_{i\in W_k}x_i',[num('window','Mesi per aggregazione',3,1,12)],'''
t<-1:120;y<-sin(2*pi*t/12)+.3*sin(2*pi*t/3)+rnorm(120,sd=.15);g<-(t-1)%/%p$window;data<-data.frame(x=t,y=y);a<-aggregate(cbind(x,y)~g,data.frame(x=t,y=y,g=g),mean);plots<-list(line_plot(data,title='Serie e aggregazioni',xl='Mese',yl='Valore')+geom_line(data=a,colour=col_geo[2],linewidth=1.2)+geom_point(data=a,colour=col_geo[2],size=2));metrics<-metric('Finestre'=nrow(a),'SD originale'=f(sd(y)),'SD aggregata'=f(sd(a$y)))
''')
add('M09',3,'smoothing','Trend, stagionalità e media mobile','Confrontare componenti note e stima mediante smoothing.','Varia l’ampiezza della media mobile e osserva attenuazione della stagionalità e perdita ai bordi.','La finestra definisce la scala temporale della sintesi; i bordi richiedono una convenzione esplicita.',r'\widehat m_t=\frac1{2k+1}\sum_{j=-k}^{k}x_{t+j}',[num('k','Semilarghezza della finestra',6,1,18)],'''
t<-1:120;trend<-t/80;y<-trend+sin(2*pi*t/12)+rnorm(120,sd=.2);sm<-as.numeric(filter(y,rep(1/(2*p$k+1),2*p$k+1),sides=2));data<-data.frame(x=t,y=y,media=sm,trend=trend);plots<-list(line_plot(data,title='Componenti e finestra mobile',xl='Mese',yl='Valore')+geom_line(aes(y=media),colour=col_geo[2],linewidth=1.1)+geom_line(aes(y=trend),colour=col_geo[3],linetype=2));metrics<-metric('Ampiezza finestra'=2*p$k+1,'Valori senza finestra completa'=sum(is.na(sm)),'RMSE rispetto al trend'=f(sqrt(mean((sm-trend)^2,na.rm=TRUE))))
''')
add('M09',4,'autocorrelazione','Ritardi e autocorrelazione','Collegare coppie temporali e dipendenza a un ritardo.','Modifica il parametro autoregressivo e il ritardo del confronto.','L’ACF riassume associazioni fra osservazioni separate da intervalli temporali definiti.',r'X_t=\phi X_{t-1}+\varepsilon_t,\quad\rho(h)=\phi^h',[num('phi','Parametro AR(1)',.7,-.9,.9,.1),num('lag','Ritardo',1,1,12)],'''
x<-ar_series(180,p$phi);h<-p$lag;data<-data.frame(x=head(x,-h),y=tail(x,-h));ac<-acf_data(x);plots<-list(point_plot(data,title='Coppie al ritardo scelto',xl='X(t−h)',yl='X(t)'),ggplot(ac,aes(x,y))+geom_segment(aes(xend=x,yend=0),colour=col_geo[1],linewidth=1)+geom_point(aes(y=p$phi^x),colour=col_geo[2],size=2)+labs(title='ACF empirica e teorica',x='Ritardo',y='Autocorrelazione'));metrics<-metric('Correlazione al ritardo'=f(cor(data$x,data$y)),'Correlazione teorica'=f(p$phi^h))
''')
add('M09',5,'stazionarieta','Processo stazionario e passeggiata casuale','Confrontare memoria e accumulo delle innovazioni.','Passa da un AR(1) stazionario a una passeggiata casuale e confronta le traiettorie.','La stazionarietà riguarda la distribuzione del processo, mentre una singola traiettoria offre evidenza limitata.',r'X_t=\phi X_{t-1}+\varepsilon_t,\quad |\phi|<1',[choice('process','Processo',[('ar','AR(1), φ = 0,7'),('rw','Passeggiata casuale, φ = 1')])],'''
paths<-replicate(6,if(p$process=='ar')ar_series(150,.7)else cumsum(rnorm(150)));data<-data.frame(x=rep(1:150,6),y=as.vector(paths),traiettoria=factor(rep(1:6,each=150)));plots<-list(line_plot(data,title='Sei traiettorie indipendenti',xl='Tempo',yl='Valore',group='traiettoria'));metrics<-metric('Varianza trasversale finale'=f(var(paths[150,])),'Varianza trasversale iniziale'=f(var(paths[1,])))
''')
add('M09',6,'differenze','Trasformazione e differenziazione','Valutare la rimozione di un trend e i suoi effetti sulla dipendenza.','Confronta livelli, differenze ordinarie e differenze stagionali.','La differenziazione cambia il processo osservato e può introdurre dipendenza quando viene applicata oltre il necessario.',r'\Delta X_t=X_t-X_{t-1},\quad\Delta_{12}X_t=X_t-X_{t-12}',[choice('difference','Trasformazione',[('0','Livelli'),('1','Differenza ordinaria'),('12','Differenza stagionale')])],'''
t<-1:180;x<-t/50+sin(2*pi*t/12)+rnorm(180,sd=.3);h<-as.numeric(p$difference);y<-if(h==0)x else diff(x,lag=h);data<-data.frame(x=seq_along(y),y=y);plots<-list(line_plot(data,title='Serie trasformata',xl='Indice temporale',yl='Valore'),line_plot(acf_data(y),title='ACF dopo trasformazione',xl='Ritardo',yl='Autocorrelazione'));metrics<-metric('Osservazioni disponibili'=length(y),'SD'=f(sd(y)),'ACF(1)'=f(acf(y,plot=FALSE)$acf[2]))
''')
add('M09',7,'diagnosi','Diagnosi ADF e KPSS mediante simulazione','Confrontare due statistiche con ipotesi nulle differenti.','Scegli un processo generatore e confronta la statistica osservata con riferimenti Monte Carlo dichiarati.','Le statistiche dipendono da termini deterministici, ritardi e stima della varianza di lungo periodo.',r'\Delta X_t=a+\gamma X_{t-1}+\eta\Delta X_{t-1}+e_t',[choice('process','Processo',[('ar','AR(1) stazionario'),('rw','Passeggiata casuale'),('trend','Trend deterministico + rumore')]),B()],'''
n<-100;adf_stat<-function(x){dx<-diff(x);y<-dx[-1];lagx<-x[2:(length(x)-1)];lagd<-head(dx,-1);coef(summary(lm(y~lagx+lagd)))[2,3]}
kpss_stat<-function(x){e<-x-mean(x);nn<-length(e);L<-4;v<-sum(e^2)/nn;for(j in 1:L)v<-v+2*(1-j/(L+1))*sum(e[(j+1):nn]*e[1:(nn-j)])/nn;sum(cumsum(e)^2)/(nn^2*v)}
x<-switch(p$process,ar=ar_series(n,.5),rw=cumsum(rnorm(n)),trend=(1:n)/15+rnorm(n));a<-adf_stat(x);k<-kpss_stat(x);aa<-replicate(p$B,adf_stat(cumsum(rnorm(n))));kk<-replicate(p$B,kpss_stat(rnorm(n)));data<-data.frame(ADF=aa,KPSS=kk);plots<-list(hist_plot(aa,'Riferimento ADF: random walk','Statistica ADF')+geom_vline(xintercept=a,colour=col_geo[2]),hist_plot(kk,'Riferimento KPSS: rumore indipendente','Statistica KPSS')+geom_vline(xintercept=k,colour=col_geo[2]));metrics<-metric('ADF osservato'=f(a),'p MC ADF'=f((1+sum(aa<=a))/(p$B+1)),'KPSS osservato'=f(k),'Coda MC KPSS: riferimento IID'=f((1+sum(kk>=k))/(p$B+1)))
''',limits='ADF con intercetta e un ritardo delle differenze; KPSS di livello con finestra Bartlett L=4. I p-value Monte Carlo sono calibrati per i generatori specificati (random walk gaussiano e rumore gaussiano indipendente), non sono i p-value tabulati dei pacchetti tseries/urca. Il confronto del modello AR richiede cautela per KPSS.')
add('M10',1,'orizzonte','Definire l’orizzonte di previsione','Confrontare futuro previsto e futuro simulato.','Aumenta l’orizzonte e osserva la propagazione dell’incertezza in un AR(1).','L’orizzonte appartiene alla definizione del compito previsionale.',r'\widehat X_{t+h}=\phi^hX_t,\quad\operatorname{Var}(e_h)=\sum_{j=0}^{h-1}\phi^{2j}',[num('h','Orizzonte',12,1,36),num('phi','Parametro AR(1)',.8,-.8,.95,.05)],'''
x<-as.numeric(arima.sim(list(ar=p$phi),n=100));h<-1:p$h;mu<-tail(x,1)*p$phi^h;se<-sqrt(sapply(h,function(k)sum(p$phi^(2*(0:(k-1))))));data<-data.frame(x=100+h,y=mu,lo=mu-1.96*se,hi=mu+1.96*se);plots<-list(ggplot(data,aes(x,y))+geom_ribbon(aes(ymin=lo,ymax=hi),fill=col_geo[1],alpha=.2)+geom_line(colour=col_geo[2],linewidth=1)+geom_line(data=data.frame(x=1:100,y=x),colour=col_geo[1])+labs(title='Previsione con parametro noto',x='Tempo',y='Valore'));metrics<-metric('Orizzonte'=p$h,'SE ultimo passo'=f(tail(se,1)))
''')
add('M10',2,'riferimenti','Previsioni di riferimento e valutazione temporale','Confrontare media, ultimo valore e riferimento stagionale.','Scegli un’origine temporale; tutti i modelli utilizzano soltanto il passato disponibile.','La valutazione deve riprodurre l’informazione accessibile al momento della previsione.',r'\operatorname{MAE}=H^{-1}\sum_h|y_{t+h}-\widehat y_{t+h}|',[num('origin','Ultimo mese disponibile',96,60,132,12)],'''
t<-1:156;y<-.02*t+sin(2*pi*t/12)+rnorm(156,sd=.2);o<-p$origin;h<-1:12;actual<-y[o+h];pred<-cbind(Media=rep(mean(y[1:o]),12),Ultimo=rep(y[o],12),Stagionale=y[(o-11):o]);data<-data.frame(x=rep(o+h,4),y=c(actual,as.vector(pred)),metodo=rep(c('Osservato',colnames(pred)),each=12));plots<-list(line_plot(data,title='Dodici mesi successivi all’origine',xl='Mese',yl='Valore',group='metodo'));metrics<-metric('MAE media'=f(mean(abs(actual-pred[,1]))),'MAE ultimo'=f(mean(abs(actual-pred[,2]))),'MAE stagionale'=f(mean(abs(actual-pred[,3]))))
''')
add('M10',3,'innovazioni','Memoria autoregressiva e innovazioni','Seguire la propagazione di una perturbazione.','Varia φ e osserva come cambia l’effetto di una singola innovazione.','La risposta a un impulso descrive la memoria del modello lineare.',r'\psi_h=\phi^h',[num('phi','Parametro autoregressivo',.7,-.9,.95,.05)],'''
h<-0:30;data<-data.frame(x=h,y=p$phi^h);plots<-list(ggplot(data,aes(x,y))+geom_segment(aes(xend=x,yend=0),linewidth=1,colour=col_geo[1])+geom_point(size=2.5,colour=col_geo[2])+labs(title='Risposta a un impulso unitario',x='Passi dopo l’impulso',y='Effetto'));metrics<-metric('Effetto dopo 5 passi'=f(p$phi^5),'Varianza stazionaria con innovazioni N(0,1)'=f(1/(1-p$phi^2)))
''')
add('M10',4,'arima','Struttura ARIMA e stagionalità','Confrontare specificazioni temporali sul medesimo campione.','Scegli un modello e confronta previsione e incertezza sui mesi successivi.','Ordini e differenze definiscono una famiglia di modelli; la verifica comprende innovazioni e prestazione futura.',r'\phi(B)(1-B)^dX_t=\theta(B)\varepsilon_t',[choice('model','Specificazione',[('ar','AR(1)'),('diff','ARIMA(1,1,0)'),('season','ARIMA(1,0,0) × (0,1,1)[12]')])],'''
t<-1:144;x<-.02*t+sin(2*pi*t/12)+as.numeric(arima.sim(list(ar=.5),n=144,sd=.2));train<-x[1:120];fit<-switch(p$model,ar=arima(train,order=c(1,0,0)),diff=arima(train,order=c(1,1,0)),season=arima(train,order=c(1,0,0),seasonal=list(order=c(0,1,1),period=12)));pr<-predict(fit,n.ahead=24);data<-data.frame(x=121:144,y=as.numeric(pr$pred),lo=as.numeric(pr$pred-1.96*pr$se),hi=as.numeric(pr$pred+1.96*pr$se),osservato=x[121:144]);plots<-list(line_plot(data,title='Previsioni oltre il campione di stima',xl='Mese',yl='Valore')+geom_ribbon(aes(ymin=lo,ymax=hi),fill=col_geo[1],alpha=.2)+geom_line(aes(y=osservato),colour=col_geo[2]));metrics<-metric('RMSE futuro'=f(sqrt(mean((data$y-data$osservato)^2))),'Copertura su questi 24 mesi'=f(mean(data$osservato>=data$lo&data$osservato<=data$hi)))
''',limits='Intervalli gaussiani condizionati ai parametri stimati. Le differenze di AIC fra modelli con differenziazioni diverse non vengono usate come criterio automatico.')
add('M10',5,'diagnostica','Diagnostica delle innovazioni stimate','Verificare la dipendenza che rimane nei residui.','Confronta un modello della sola media con un AR(1).','La mancata rilevazione di autocorrelazione non esaurisce la verifica del modello.',r'Q=n(n+2)\sum_{h=1}^m\frac{\widehat\rho_h^2}{n-h}',[choice('model','Modello adattato',[('mean','Sola media'),('ar','AR(1)')])],'''
x<-as.numeric(arima.sim(list(ar=.75),n=180));order<-if(p$model=='ar')1 else 0;fit<-arima(x,order=c(order,0,0));e<-as.numeric(resid(fit));ac<-acf_data(e);data<-data.frame(tempo=seq_along(e),residuo=e);bt<-Box.test(e,lag=12,type='Ljung-Box',fitdf=order);plots<-list(line_plot(ac,title='ACF delle innovazioni stimate',xl='Ritardo',yl='Autocorrelazione')+geom_hline(yintercept=c(-1,1)*1.96/sqrt(length(e)),linetype=2));metrics<-metric('Ljung–Box Q'=f(bt$statistic),'p approssimato'=f(bt$p.value),'Gradi di libertà'=12-order)
''')
add('M10',6,'copertura','Valutazione a origine mobile','Valutare ripetutamente una previsione usando solo il passato.','Cambia l’orizzonte e confronta errori e copertura degli intervalli.','La valutazione temporale conserva l’ordine delle osservazioni e rende esplicite le origini del confronto.',r'e_{t,h}=X_{t+h}-\widehat X_{t+h\mid t}',[num('h','Orizzonte di valutazione',3,1,12)],'''
x<-as.numeric(arima.sim(list(ar=.7),n=200));orig<-seq(60,180,3);out<-t(sapply(orig,function(o){fit<-arima(x[1:o],order=c(1,0,0));pr<-predict(fit,n.ahead=p$h);c(as.numeric(tail(pr$pred,1)),as.numeric(tail(pr$se,1)),x[o+p$h])}));data<-data.frame(x=orig,y=out[,3]-out[,1],copre=abs(out[,3]-out[,1])<=1.96*out[,2]);plots<-list(point_plot(data,title='Errori a origine mobile',xl='Origine',yl='Osservato − previsto')+geom_hline(yintercept=0,linetype=2));metrics<-metric('RMSE'=f(sqrt(mean(data$y^2))),'Copertura'=f(mean(data$copre)),'Origini'=length(orig))
''')
add('M10',7,'multivariato','Contributo predittivo di una seconda serie','Confrontare un modello autoregressivo con uno che include un predittore ritardato.','Varia il contributo della seconda serie e confronta gli errori futuri.','Un miglioramento predittivo condizionato al modello non stabilisce da solo una relazione causale.',r'Y_t=aY_{t-1}+bX_{t-1}+\varepsilon_t',[num('b','Contributo della seconda serie',.6,0,1,.1)],'''
n<-220;x<-ar_series(n,.7);y<-numeric(n);for(i in 2:n)y[i]<-.4*y[i-1]+p$b*x[i-1]+rnorm(1,sd=.5);d<-data.frame(y=y[-1],ylag=head(y,-1),xlag=head(x,-1));tr<-1:150;te<-151:nrow(d);a<-lm(y~ylag,d[tr,]);b<-lm(y~ylag+xlag,d[tr,]);pa<-predict(a,d[te,]);pb<-predict(b,d[te,]);data<-data.frame(x=te,y=d$y[te],solo=pa,multi=pb);plots<-list(line_plot(data,title='Previsione a un passo sul periodo separato',xl='Tempo',yl='Risposta')+geom_line(aes(y=solo),colour=col_geo[2])+geom_line(aes(y=multi),colour=col_geo[3]));metrics<-metric('RMSE solo Y'=f(sqrt(mean((d$y[te]-pa)^2))),'RMSE Y e X'=f(sqrt(mean((d$y[te]-pb)^2))),'Coefficiente X stimato'=f(coef(b)[3]))
''')
add('M11',1,'supporto','Dato puntuale e supporto areale','Confrontare valori locali e medie su superfici crescenti.','Aumenta il lato del supporto e osserva l’attenuazione della variabilità.','Una misura riferita a un’area sintetizza il campo sul supporto dichiarato.',r'Z_A=|A|^{-1}\int_A Z(s)\,ds',[num('block','Lato del blocco [celle]',4,1,8)],'''
g<-expand.grid(x=1:32,y=1:32);g$z<-sin(g$x/3)+cos(g$y/5)+rnorm(nrow(g),sd=.3);g$gx<-(g$x-1)%/%p$block;g$gy<-(g$y-1)%/%p$block;a<-aggregate(z~gx+gy,g,mean);data<-g;data$media<-a$z[match(paste(g$gx,g$gy),paste(a$gx,a$gy))];plots<-list(map_plot(data,'z','Campo a supporto puntuale'),map_plot(data,'media','Medie sui blocchi'));metrics<-metric('SD locale'=f(sd(g$z)),'SD delle medie di blocco'=f(sd(a$z)))
''')
add('M11',2,'coordinate','Coordinate e metrica delle distanze','Verificare la dipendenza della distanza dalle unità degli assi.','Modifica la conversione della coordinata Est e osserva come cambia la geometria.','Una distanza euclidea richiede coordinate espresse in unità compatibili.',r'd_{ij}=\sqrt{(x_i-x_j)^2+(y_i-y_j)^2}',[num('scale','Fattore applicato alla coordinata Est',1,.1,3,.1)],'''
data<-data.frame(x=c(0,3,0,3)*p$scale,y=c(0,0,4,4),punto=c('A','B','C','D'));dd<-as.matrix(dist(data[,c('x','y')]));plots<-list(point_plot(data,title='Coordinate locali metriche',xl='Est [km]',yl='Nord [km]')+geom_text(aes(label=punto),vjust=-1,size=5)+coord_equal()+expand_limits(y=5));metrics<-metric('Distanza A–D [km]'=f(dd[1,4]),'Distanza A–B [km]'=f(dd[1,2]))
''')
add('M11',3,'aggregazione','Aggregazioni territoriali e confini','Osservare come i confini delle zone modificano una sintesi.','Sposta il confine fra due zone e confronta le rispettive medie.','Una media territoriale dipende da dominio, supporto e criterio di appartenenza.',r'\bar z_A=\frac{\sum_{i\in A}w_i z_i}{\sum_{i\in A}w_i}',[num('cut','Confine Est fra zone [km]',10,3,17)],'''
data<-expand.grid(x=1:20,y=1:20);data$z<-data$x/3+sin(data$y/3);data$zona<-ifelse(data$x<=p$cut,'Ovest','Est');a<-aggregate(z~zona,data,mean);plots<-list(map_plot(data,title='Campo e confine amministrativo')+geom_vline(xintercept=p$cut+.5,colour='#FCF8E8',linewidth=1.2));metrics<-metric('Media Ovest'=f(a$z[a$zona=='Ovest']),'Media Est'=f(a$z[a$zona=='Est']),'Celle Ovest'=sum(data$zona=='Ovest'))
''')
add('M11',4,'vicinati','Vicinati e matrici dei pesi','Costruire relazioni spaziali a partire da una soglia di distanza.','Aumenta il raggio e confronta numero di vicini e normalizzazione per riga.','La matrice dei pesi esprime una scelta di relazione spaziale che precede il calcolo dell’associazione.',r'w_{ij}=\mathbf1(0<d_{ij}\le r)',[num('radius','Raggio del vicinato [km]',1.1,.5,3,.1),choice('normal','Pesi',[('binary','Binari'),('row','Normalizzati per riga')])],'''
xy<-expand.grid(x=1:8,y=1:8);dd<-as.matrix(dist(xy));w<-1*(dd>0&dd<=p$radius);deg<-rowSums(w);if(p$normal=='row')w<-w/pmax(deg,1);data<-data.frame(x=xy$x,y=xy$y,z=deg);plots<-list(map_plot(data,title='Numero di vicini per sito'));metrics<-metric('Somma dei pesi'=sum(w),'Minimo vicini'=min(deg),'Massimo vicini'=max(deg),'Siti isolati'=sum(deg==0))
''')
add('M11',5,'moran','Associazione spaziale e permutazioni','Confrontare Moran I con un riferimento di etichette permutate.','Varia il gradiente del campo e osserva l’associazione globale.','La permutazione conserva posizioni e pesi; un gradiente può produrre associazione e richiede interpretazione.',r'I=\frac n{S_0}\frac{\sum_{ij}w_{ij}(z_i-\bar z)(z_j-\bar z)}{\sum_i(z_i-\bar z)^2}',[num('gradient','Gradiente del campo',1,0,3,.25),B()],'''
xy<-expand.grid(x=1:8,y=1:8);dd<-as.matrix(dist(xy));w<-1*(dd>0&dd<=1.1);z<-p$gradient*xy$x+rnorm(64);mi<-function(v){u<-v-mean(v);length(v)/sum(w)*sum(w*outer(u,u))/sum(u^2)};obs<-mi(z);vals<-replicate(p$B,mi(sample(z)));data<-data.frame(x=xy$x,y=xy$y,z=z);plots<-list(map_plot(data,title='Campo osservato'),hist_plot(vals,'Moran I sotto permutazione','I')+geom_vline(xintercept=obs,colour=col_geo[2]));metrics<-metric('Moran I'=f(obs),'p MC coda superiore'=f((1+sum(vals>=obs))/(p$B+1)),'S0'=sum(w))
''')
add('M11',6,'variogramma','Dalle coppie al semivariogramma','Costruire la semivarianza per classi di distanza.','Cambia l’ampiezza delle classi e il gradiente; confronta semivarianze e numerosità delle coppie.','Le coppie condividono osservazioni e la curva empirica riflette anche eventuali componenti non stazionarie.',r'\widehat\gamma(h)=\frac1{2|N(h)|}\sum_{(i,j)\in N(h)}(z_i-z_j)^2',[num('width','Ampiezza classi [km]',1,.5,3,.5),num('gradient','Gradiente verso Est',0,0,2,.25)],'''
xy<-expand.grid(x=1:8,y=1:8);z<-sin(xy$x/2)+cos(xy$y/2)+p$gradient*xy$x+rnorm(64,sd=.2);dd<-as.matrix(dist(xy));sel<-upper.tri(dd);pairs<-data.frame(distanza=dd[sel],semivarianza=(outer(z,z,'-')^2/2)[sel]);pairs$classe<-floor(pairs$distanza/p$width);a<-aggregate(cbind(distanza,semivarianza)~classe,pairs,mean);a$coppie<-as.numeric(table(pairs$classe));data<-a;plots<-list(point_plot(a,'distanza','semivarianza','Semivariogramma empirico','Distanza [km]','Semivarianza [unità²]')+geom_line(colour=col_geo[1])+geom_text(aes(label=coppie),vjust=-.8,size=4)+expand_limits(y=max(a$semivarianza)*1.15));metrics<-metric('Coppie non ordinate'=nrow(pairs),'Classi non vuote'=nrow(a),'Minimo coppie per classe'=min(a$coppie))
''')
add('M11',7,'copertura','Copertura geografica del campione','Misurare la distanza delle aree dai siti osservati.','Concentra la campagna nel settore occidentale e confronta le distanze al sito più vicino.','La copertura territoriale contribuisce a delimitare la trasferibilità delle conclusioni.',r'd_{min}(s)=\min_i\lVert s-s_i\rVert',[num('extent','Estensione campionata verso Est [km]',10,3,10),N(30)],'''
xy<-cbind(runif(p$n,0,p$extent),runif(p$n,0,10));grid<-expand.grid(x=seq(0,10,length.out=35),y=seq(0,10,length.out=35));grid$z<-apply(dist_cross(as.matrix(grid),xy),1,min);data<-grid;plots<-list(map_plot(data,title='Distanza al sito più vicino')+geom_point(data=data.frame(x=xy[,1],y=xy[,2]),aes(x,y),inherit.aes=FALSE,size=1.5));metrics<-metric('Distanza massima [km]'=f(max(grid$z)),'Distanza media [km]'=f(mean(grid$z)))
''')
add('M11',8,'interpolazione','Interpolazione e verifica geografica','Confrontare IDW e un riferimento mediante campioni separati nello spazio.','Cambia potenza IDW e protocollo di verifica mantenendo il medesimo campo.','Il test geografico misura il trasferimento alla regione esclusa dall’adattamento.',r'\widehat z(s)=\frac{\sum_i d(s,s_i)^{-p}z_i}{\sum_i d(s,s_i)^{-p}}',[num('power','Potenza IDW',2,0,5,.5),choice('split','Separazione',[('random','Casuale'),('east','Settore orientale escluso')])],'''
xy<-expand.grid(x=1:8,y=1:8);z<-sin(xy$x/2)+xy$x/4+cos(xy$y/3);test<-if(p$split=='east')which(xy$x>5)else sample(1:64,24);train<-setdiff(1:64,test);pr<-idw(as.matrix(xy[train,]),z[train],as.matrix(xy[test,]),p$power);data<-data.frame(x=xy$x[test],y=xy$y[test],osservato=z[test],previsto=pr,errore=z[test]-pr);plots<-list(point_plot(data,'osservato','previsto','Valutazione sui siti esclusi','Osservato','Previsto')+geom_abline(intercept=0,slope=1,linetype=2));metrics<-metric('Siti di stima'=length(train),'Siti di test'=length(test),'RMSE IDW'=f(sqrt(mean((pr-z[test])^2))),'RMSE media di training'=f(sqrt(mean((mean(z[train])-z[test])^2))))
''')
add('M12',1,'griglia','Geometria di una griglia raster','Collegare numero di celle, risoluzione e superficie.','Varia la dimensione delle celle mantenendo costanti righe e colonne.','La risoluzione e l’estensione del raster sono grandezze distinte.',r'A=n_rn_c\Delta x\Delta y',[num('cell','Lato della cella [m]',30,5,100,5)],'''
data<-expand.grid(x=(1:20-.5)*p$cell,y=(1:16-.5)*p$cell);data$z<-sin(data$x/(4*p$cell))+cos(data$y/(5*p$cell));plots<-list(map_plot(data,title='Griglia georeferenziata locale',xl='Est [m]',yl='Nord [m]'));metrics<-metric('Celle'=320,'Superficie [ha]'=320*p$cell^2/10000,'Estensione Est [m]'=20*p$cell)
''')
add('M12',2,'maschere','Maschere, dominio e superficie valida','Distinguere celle escluse e celle a valore nullo.','Allarga la maschera e confronta copertura e media delle celle valide.','La maschera modifica il dominio della sintesi; il valore zero appartiene invece alla scala della variabile.',r'\bar z_D=\frac{\sum_i z_iI_i}{\sum_i I_i}',[num('radius','Raggio della maschera [celle]',5,1,12)],'''
data<-expand.grid(x=1:24,y=1:24);data$z<-100+data$x+data$y;excluded<-(data$x-12)^2+(data$y-12)^2<p$radius^2;original<-data$z;data$z[excluded]<-NA;plots<-list(map_plot(data,title='Dominio valido e celle escluse',xl='Colonna [indice]',yl='Riga [indice]'));metrics<-metric('Copertura'=f(mean(!excluded)),'Media celle valide'=f(mean(data$z,na.rm=TRUE)),'Media con sostituzione impropria a zero'=f(mean(ifelse(excluded,0,original))))
''')
add('M12',3,'ricampionamento','Aggregazione e ricampionamento di una griglia','Confrontare risoluzioni senza attribuire nuova informazione ai pixel interpolati.','Varia il fattore di aggregazione e osserva attenuazione dei dettagli e conservazione della media.', 'Con blocchi completi e celle di uguale area, la media delle medie conserva la media del raster.',r'\bar z_{blocchi}=\bar z_{celle}\quad\text{per blocchi completi di uguale area}',[choice('block','Lato dei blocchi',[('1','1 cella'),('2','2 celle'),('4','4 celle'),('8','8 celle')])],'''
k<-as.numeric(p$block);data<-expand.grid(x=1:32,y=1:32);data$z<-sin(data$x/2)+cos(data$y/3);data$gx<-(data$x-1)%/%k;data$gy<-(data$y-1)%/%k;a<-aggregate(z~gx+gy,data,mean);a$x<-a$gx*k+(k+1)/2;a$y<-a$gy*k+(k+1)/2;plots<-list(map_plot(data,title='Raster originale',xl='Colonna [indice]',yl='Riga [indice]'),map_plot(a,title='Raster aggregato',xl='Colonna [indice]',yl='Riga [indice]'));metrics<-metric('Celle originali'=nrow(data),'Celle aggregate'=nrow(a),'Scarto della media'=f(mean(data$z)-mean(a$z),8))
''')
add('M12',4,'pendenza','Gradiente, pendenza ed esposizione','Ricostruire derivate da differenze centrate e unità metriche.','Varia le pendenze del piano e confronta risultati numerici e soluzione analitica.','L’esposizione è definita dalla direzione di massima discesa; su un piano orizzontale rimane indeterminata.',r'g_x=\frac{z_{i+1,j}-z_{i-1,j}}{2\Delta x},\quad\alpha=\arctan\sqrt{g_x^2+g_y^2}',[num('gx','Gradiente verso Est [m/m]',.12,-.4,.4,.02),num('gy','Gradiente verso Nord [m/m]',.08,-.4,.4,.02)],'''
data<-expand.grid(x=seq(0,570,30),y=seq(0,570,30));data$z<-900+p$gx*data$x+p$gy*data$y;z<-matrix(data$z,20,20);dx<-(z[3:20,2:19]-z[1:18,2:19])/60;dy<-(z[2:19,3:20]-z[2:19,1:18])/60;slope<-atan(sqrt(dx^2+dy^2))*180/pi;aspect<-if(abs(p$gx)+abs(p$gy)<1e-10)NA else (atan2(-p$gx,-p$gy)*180/pi)%%360;plots<-list(map_plot(data,title='Piano a gradiente noto',xl='Est [m]',yl='Nord [m]'));metrics<-metric('Pendenza [gradi]'=f(mean(slope)),'Pendenza [%]'=f(100*sqrt(p$gx^2+p$gy^2)),'Esposizione [gradi da Nord]'=if(is.na(aspect))'Indeterminata'else f(aspect),'Celle interne'=length(slope))
''')
add('M12',5,'hillshade','Illuminazione del rilievo','Separare forma del terreno e condizioni di illuminazione.','Ruota l’azimut della sorgente luminosa mantenendo invariato il rilievo.','L’ombreggiatura locale dipende dal prodotto scalare fra normale e luce; non rappresenta ombre proiettate.',r'I=\max(0,\widehat n\cdot\widehat l)',[num('azimuth','Azimut della luce [gradi da Nord]',315,0,360,15),num('altitude','Elevazione della luce [gradi]',40,5,85,5)],'''
data<-expand.grid(x=seq(-3,3,length.out=50),y=seq(-3,3,length.out=50));data$z<-2*exp(-(data$x^2+data$y^2)/3);gx<--2*data$x/3*data$z;gy<--2*data$y/3*data$z;az<-p$azimuth*pi/180;el<-p$altitude*pi/180;data$luce<-pmax(0,(-gx*cos(el)*sin(az)-gy*cos(el)*cos(az)+sin(el))/sqrt(gx^2+gy^2+1));plots<-list(map_plot(data,'luce','Illuminazione locale del rilievo',xl='x [unità locali]',yl='y [unità locali]'));metrics<-metric('Intensità minima'=f(min(data$luce)),'Intensità massima'=f(max(data$luce)),'Quota massima invariata'=f(max(data$z)))
''')
add('M12',6,'indici','Bande spettrali e indice normalizzato','Esaminare il ruolo di numeratore e denominatore in un indice.','Modifica riflettanza rossa e infrarossa e osserva l’indice e la sensibilità a piccoli segnali.','L’indice richiede un denominatore valido e conserva il significato delle bande utilizzate.',r'NDVI=\frac{NIR-R}{NIR+R}',[num('nir','Riflettanza NIR',.5,0,1,.05),num('red','Riflettanza rossa',.2,0,1,.05)],'''
s<-p$nir+p$red;ndvi<-if(s>1e-8)(p$nir-p$red)/s else NA;data<-data.frame(gruppo=c('NIR','Rosso'),valore=c(p$nir,p$red));plots<-list(bar_plot(data,title='Bande sintetiche',yl='Riflettanza')+coord_cartesian(ylim=c(0,1)));metrics<-metric('NDVI'=if(is.na(ndvi))'Non definito'else f(ndvi),'Denominatore'=s,'Derivata rispetto a NIR'=if(s>1e-8)f(2*p$red/s^2)else'Non definita')
''')
add('M12',7,'zone','Sintesi zonali e dipendenza delle celle','Confrontare numero di pixel e unità informative.','Aumenta la dimensione delle zone e confronta variabilità fra celle e fra medie zonali.','La numerosità dei pixel non equivale al numero di osservazioni indipendenti.',r'\bar z_A=\sum_{i\in A}w_i z_i/\sum_{i\in A}w_i',[choice('block','Lato della zona',[('2','2 celle'),('4','4 celle'),('8','8 celle')])],'''
k<-as.numeric(p$block);data<-expand.grid(x=1:32,y=1:32);data$z<-sin(data$x/5)+cos(data$y/5)+rnorm(1024,sd=.1);data$zona<-interaction((data$x-1)%/%k,(data$y-1)%/%k);a<-aggregate(z~zona,data,mean);plots<-list(hist_plot(a$z,'Distribuzione delle medie zonali','Media zonale'));metrics<-metric('Pixel'=1024,'Zone'=nrow(a),'SD fra pixel'=f(sd(data$z)),'SD fra zone'=f(sd(a$z)))
''')
add('M12',8,'memoria','Dimensioni del raster e memoria','Quantificare la crescita del costo di una griglia.','Varia numero di righe, colonne e bande; confronta la memoria dei soli valori con il budget disponibile.','Il costo di elaborazione comprende anche maschere, copie e oggetti temporanei.',r'M=n_rn_cn_b b',[num('rows','Righe',1000,100,10000,100),num('cols','Colonne',1000,100,10000,100),num('bands','Bande',4,1,20)],'''
k<-1:8;mem<-p$rows*p$cols*p$bands*8/1024^2;data<-data.frame(x=k,y=k*mem);plots<-list(line_plot(data,title='Memoria dei valori e copie simultanee',xl='Copie del raster',yl='MiB')+geom_point(size=2,colour=col_geo[1]));metrics<-metric('Memoria di una copia [MiB]'=f(mem),'Valori'=p$rows*p$cols*p$bands,'Byte per valore'=8)
''',limits='Calcolo del costo teorico di valori double. Non viene allocato il raster richiesto; overhead, compressione e memoria del dispositivo sono esclusi dal conteggio.')
add('M13',1,'ancore','Ancore cronologiche e convenzioni temporali','Collegare profondità, età e riferimento temporale.','Sposta l’età dell’ancora intermedia mantenendo l’ordine cronologico.','Le ancore associano età e profondità; la convenzione BP usa il 1950 come riferimento.',r'a_{astronomico}=1950-t_{cal\,BP}',[num('age','Età dell’ancora a 80 cm [anni cal BP]',900,400,1500,50)],'''
data<-data.frame(profondita=c(0,40,80,120,160),eta=c(0,350,p$age,1700,2200));plots<-list(point_plot(data,'eta','profondita','Ancore età–profondità','Età [anni cal BP]','Profondità [cm]')+geom_line()+scale_y_reverse());metrics<-metric('Anno astronomico dell’ancora'=1950-p$age,'Ancore'=nrow(data),'Cronologia monotona'=all(diff(data$eta)>0))
''',limits='Età già espresse in anni calibrati BP. La conversione aritmetica rispetto al 1950 non esegue calibrazione radiocarbonica.')
add('M13',2,'interpolazione','Interpolazione e tassi di accumulo','Ricostruire una cronologia fra ancore e valutarne la pendenza.','Sposta la profondità di interrogazione e confronta età interpolata e tassi dei segmenti.','L’interpolazione lineare assume un tasso costante entro ciascun intervallo fra ancore.',r't(z)=t_i+\frac{z-z_i}{z_{i+1}-z_i}(t_{i+1}-t_i),\quad r_i=\frac{\Delta z_i}{\Delta t_i}',[num('depth','Profondità da interrogare [cm]',70,0,180,5)],'''
z<-c(0,40,80,120,160);t<-c(0,350,900,1700,2200);d<-seq(0,160,2);data<-data.frame(profondita=d,eta=approx(z,t,d,rule=1)$y);age<-approx(z,t,p$depth,rule=1)$y;r<-diff(z)/diff(t)*10;plots<-list(line_plot(data,'eta','profondita','Cronologia interpolata','Età [anni cal BP]','Profondità [cm]')+scale_y_reverse());metrics<-metric('Età richiesta'=if(is.na(age))'Fuori dominio'else f(age),'Tasso minimo [mm/anno]'=f(min(r)),'Tasso massimo [mm/anno]'=f(max(r)))
''')
add('M13',3,'incertezza','Scenari cronologici e propagazione','Costruire cronologie perturbate conservando l’associazione fra età e profondità.','Aumenta l’incertezza delle ancore e osserva bande puntuali e scenari rifiutati.','La selezione degli scenari monotoni condiziona la distribuzione delle cronologie accettate.',r't_b(z)=\operatorname{interp}\{(z_i,t_{i,b})\}',[num('sd','SD delle ancore [anni]',100,20,400,20),B()],'''
z<-c(0,40,80,120,160);t<-c(0,350,900,1700,2200);draws<-matrix(rep(t,p$B),nrow=5)+matrix(rnorm(5*p$B,sd=p$sd),nrow=5);ok<-apply(draws,2,function(v)all(diff(v)>0));stopifnot(sum(ok)>2);d<-seq(0,160,4);ages<-apply(draws[,ok,drop=FALSE],2,function(a)approx(z,a,d)$y);q<-t(apply(ages,1,quantile,c(.025,.5,.975)));data<-data.frame(profondita=d,lo=q[,1],eta=q[,2],hi=q[,3]);plots<-list(ggplot(data,aes(profondita,eta))+geom_ribbon(aes(ymin=lo,ymax=hi),fill=col_geo[1],alpha=.25)+geom_line(colour=col_geo[1],linewidth=1)+labs(title='Banda puntuale degli scenari accettati',x='Profondità [cm]',y='Età [anni cal BP]'));metrics<-metric('Scenari generati'=p$B,'Accettati'=sum(ok),'Rifiutati'=sum(!ok),'Ampiezza mediana banda [anni]'=f(median(data$hi-data$lo)))
''',limits='Perturbazioni gaussiane indipendenti delle ancore: scenari di sensibilità, non posteriori bayesiane. Bande puntuali al 95% condizionate alla monotonicità; nessun riordinamento separato delle età.')
add('M13',4,'proxy','Risoluzione temporale di un proxy','Confrontare un campionamento uniforme in profondità con il suo supporto temporale.','Cambia il passo di campionamento e osserva la durata degli intervalli.','Una risoluzione costante in profondità può corrispondere a risoluzioni temporali differenti.',r'\Delta t_i=t(z_{i+1})-t(z_i)',[num('step','Passo in profondità [cm]',5,1,20)],'''
z<-c(0,40,80,120,160);t<-c(0,350,900,1700,2200);d<-seq(0,160,p$step);age<-approx(z,t,d)$y;proxy<-sin(d/8)+.4*cos(d/3);data<-data.frame(profondita=d,eta=age,proxy=proxy);plots<-list(line_plot(data,'eta','proxy','Proxy nella scala temporale','Età [anni cal BP]','Proxy')+geom_point(colour=col_geo[1],size=2));metrics<-metric('Campioni'=length(d),'Intervallo minimo [anni]'=f(min(diff(age))),'Intervallo massimo [anni]'=f(max(diff(age))))
''')
add('M13',5,'hiatus','Discontinuità e sensibilità della cronologia','Rappresentare un intervallo temporale privo di sedimentazione.','Modifica la durata dello hiatus e segui lo spostamento delle età oltre la discontinuità.','Lo hiatus produce un salto nella funzione età–profondità e richiede rami distinti nel disegno.',r't_H(z)=t(z)+H\mathbf1(z>80)',[num('hiatus','Durata dello hiatus [anni]',400,0,1000,50)],'''
d<-seq(0,160,2);t<-approx(c(0,40,80,120,160),c(0,350,900,1700,2200),d)$y;data<-data.frame(profondita=d,eta=t+p$hiatus*(d>80),ramo=factor(d>80));plots<-list(ggplot(data,aes(eta,profondita,group=ramo))+geom_line(colour=col_geo[1],linewidth=1.1)+geom_hline(yintercept=80,linetype=2,colour=col_geo[2])+scale_y_reverse()+labs(title='Rami separati della cronologia',x='Età [anni cal BP]',y='Profondità [cm]'));metrics<-metric('Salto cronologico [anni]'=p$hiatus,'Età a 120 cm'=1700+p$hiatus)
''')
add('M13',6,'durate','Durate entro uno stesso scenario','Propagare la covarianza nella durata fra due eventi.','Varia la correlazione fra le età e confronta dispersione delle durate e soluzione analitica.','La durata va calcolata accoppiando le età appartenenti al medesimo scenario.',r'\operatorname{Var}(T_2-T_1)=\sigma_1^2+\sigma_2^2-2\rho\sigma_1\sigma_2',[num('rho','Correlazione fra le età',.6,-.8,.9,.1),B()],'''
u<-rnorm(p$B);v<-p$rho*u+sqrt(1-p$rho^2)*rnorm(p$B);t1<-500+80*u;t2<-1000+100*v;data<-data.frame(t1=t1,t2=t2,durata=t2-t1);plots<-list(hist_plot(data$durata,'Durate entro scenario','Durata [anni]'));metrics<-metric('SD simulata [anni]'=f(sd(data$durata)),'SD analitica [anni]'=f(sqrt(80^2+100^2-2*p$rho*80*100)),'Durata media'=f(mean(data$durata)))
''')
add('M14',1,'massimi','Dalle osservazioni ai massimi annuali','Esaminare la distribuzione dei massimi di blocchi indipendenti.','Aumenta le osservazioni per blocco mantenendo fissa la distribuzione di origine.','Il massimo cresce con il numero di opportunità di osservare valori elevati.',r'P(M_m\le x)=F(x)^m',[num('m','Osservazioni per blocco',30,5,365,5),B()],'''
mx<-replicate(p$B,max(rexp(p$m,rate=1)));data<-data.frame(massimo=mx);plots<-list(hist_plot(mx,'Massimi di blocchi indipendenti','Massimo'));q<--log(1-.95^(1/p$m));metrics<-metric('Media dei massimi'=f(mean(mx)),'Quantile teorico 95%'=f(q),'Quantile empirico 95%'=f(quantile(mx,.95)))
''',limits='Osservazioni esponenziali indipendenti con tasso unitario. La dimensione del blocco è un’astrazione didattica; la dipendenza giornaliera richiede un modello ulteriore.')
add('M14',2,'ritorno','Tempo di ritorno e orizzonte temporale','Distinguere probabilità annuale, attesa e rischio cumulato.','Varia tempo di ritorno e durata dell’esposizione.','Il tempo di ritorno è un’attesa del modello e non impone intervalli regolari fra eventi.',r'P(N_H\ge1)=1-(1-1/T)^H',[num('T','Tempo di ritorno [anni]',100,2,500,2),num('H','Orizzonte [anni]',50,1,150)],'''
h<-1:150;data<-data.frame(x=h,y=1-(1-1/p$T)^h);plots<-list(line_plot(data,title='Almeno un superamento nell’orizzonte',xl='Orizzonte [anni]',yl='Probabilità')+geom_vline(xintercept=p$H,linetype=2)+coord_cartesian(ylim=c(0,1)));metrics<-metric('Probabilità annuale'=f(1/p$T),'Probabilità cumulata'=f(1-(1-1/p$T)^p$H),'Numero atteso di superamenti'=f(p$H/p$T))
''',limits='Anni indipendenti con probabilità annuale costante. Con dipendenza o non stazionarietà la formula cumulata va modificata.')
add('M14',3,'gumbel','Adattamento di Gumbel ai massimi','Confrontare distribuzione empirica e modello stimato ai momenti.','Varia la lunghezza del record e osserva la variabilità dei parametri stimati.','La verifica dell’adattamento deve accompagnare l’estrapolazione alle code.',r'F(x)=\exp\{-\exp[-(x-\mu)/\beta]\},\quad\beta>0',[num('n','Anni osservati',40,15,120,5)],'''
x<-480-90*log(-log(runif(p$n)));beta<-sd(x)*sqrt(6)/pi;mu<-mean(x)-.5772156649015329*beta;u<-(1:p$n)/ (p$n+1);q<-mu-beta*log(-log(u));data<-data.frame(x=q,y=sort(x));plots<-list(point_plot(data,title='Quantili teorici e osservati',xl='Quantile Gumbel stimato',yl='Massimo osservato')+geom_abline(intercept=0,slope=1,linetype=2));metrics<-metric('Posizione stimata'=f(mu),'Scala stimata'=f(beta),'Anni osservati'=p$n)
''')
add('M14',4,'livelli-rari','Livelli di ritorno e incertezza bootstrap','Esaminare l’incertezza di un livello raro condizionatamente al modello.','Aumenta il tempo di ritorno e confronta stima puntuale e distribuzione bootstrap.','L’estrapolazione oltre la lunghezza del record aumenta la dipendenza dal modello di coda.',r'q_T=\mu-\beta\log[-\log(1-1/T)]',[num('n','Anni osservati',40,15,120,5),num('T','Tempo di ritorno [anni]',100,2,500,2),B()],'''
x<-480-90*log(-log(runif(p$n)));qfun<-function(v){b<-sd(v)*sqrt(6)/pi;m<-mean(v)-.5772156649015329*b;m-b*log(-log1p(-1/p$T))};q<-qfun(x);boot<-replicate(p$B,qfun(sample(x,replace=TRUE)));ci<-quantile(boot,c(.025,.975));data<-data.frame(livello=boot);plots<-list(hist_plot(boot,'Livello raro nelle repliche bootstrap','Livello di ritorno')+geom_vline(xintercept=q,colour=col_geo[2]));metrics<-metric('Livello stimato'=f(q),'Limite 2,5%'=f(ci[1]),'Limite 97,5%'=f(ci[2]),'T maggiore del record'=p$T>p$n)
''')
add('M14',5,'gev','Sensibilità alla forma della coda GEV','Confrontare livelli rari sotto forme di coda differenti.','Varia ξ mantenendo fisse posizione e scala; osserva il limite superiore quando ξ è negativo.','Le curve rappresentano scenari di sensibilità e non adattamenti alternativi allo stesso record.',r'q_T=\begin{cases}\mu+\dfrac{\sigma}{\xi}\{[-\log(1-1/T)]^{-\xi}-1\},&\xi\ne0\\\mu-\sigma\log[-\log(1-1/T)],&\xi=0\end{cases}',[num('xi','Parametro di forma ξ',0,-.3,.3,.05),num('T','Tempo di ritorno [anni]',100,2,500,2)],'''
qgev<-function(T,xi){u<--log1p(-1/T);if(abs(xi)<1e-8)480-90*log(u)else 480+90*expm1(-xi*log(u))/xi};T<-exp(seq(log(2),log(500),length.out=150));data<-data.frame(x=T,y=qgev(T,p$xi));plots<-list(line_plot(data,title='Scenario GEV: μ=480, σ=90',xl='Tempo di ritorno [anni]',yl='Livello')+scale_x_log10(breaks=c(2,5,10,20,50,100,200,500))+geom_vline(xintercept=p$T,linetype=2));metrics<-metric('Livello al T scelto'=f(qgev(p$T,p$xi)),'Limite superiore'=if(p$xi<0)f(480-90/p$xi)else'Non finito','Forma ξ'=p$xi)
''')
add('M14',6,'episodi','Superamenti e separazione degli episodi','Distinguere giorni sopra soglia ed eventi temporali.','Modifica soglia e intervallo minimo fra episodi; osserva la riclassificazione dei superamenti.','La definizione di episodio appartiene al modello operativo dell’evento.',r'N_{episodi}=\begin{cases}0,&k=0\\1+\sum_{j=2}^k\mathbf1(t_j-t_{j-1}>r),&k>0\end{cases}',[num('threshold','Soglia',1,.2,2.5,.1),num('gap','Separazione minima [giorni]',3,1,10)],'''
x<-ar_series(200,.85);idx<-which(x>p$threshold);episode<-if(length(idx))cumsum(c(1,diff(idx)>p$gap))else integer();data<-data.frame(giorno=1:200,valore=x,supera=x>p$threshold);plots<-list(line_plot(data,'giorno','valore','Superamenti della soglia','Giorno','Valore')+geom_hline(yintercept=p$threshold,colour=col_geo[2],linetype=2)+geom_point(data=data[idx,,drop=FALSE],colour=col_geo[2],size=2));metrics<-metric('Giorni sopra soglia'=length(idx),'Episodi'=if(length(idx))max(episode)else 0,'Separazione adottata'=p$gap)
''')
add('M14',7,'conseguenze','Pericolosità e conseguenze','Calcolare la perdita attesa per classi di evento mutuamente esclusive.','Varia esposizione e vulnerabilità mantenendo fisse le probabilità delle classi.','Il rischio dipende sia dalla frequenza degli eventi sia dalle conseguenze associate.',r'E(L)=\sum_kp_kL_k',[num('exposure','Moltiplicatore dell’esposizione',1,.2,3,.2),num('vulnerability','Moltiplicatore della vulnerabilità',1,.2,2,.2)],'''
prob<-c(.08,.015,.005);loss<-c(10000,100000,1000000)*p$exposure*p$vulnerability;data<-data.frame(gruppo=c('Moderato','Severo','Estremo'),probabilita=prob,perdita=loss,valore=prob*loss);plots<-list(bar_plot(data,title='Contributi alla perdita attesa',yl='Unità monetarie / anno'));metrics<-metric('Perdita attesa annua'=f(sum(prob*loss)),'Probabilità annua di una classe dannosa'=sum(prob),'Esposizione relativa'=p$exposure)
''',limits='Le tre classi sono mutuamente esclusive, con probabilità annuali 0,08, 0,015 e 0,005; la classe rimanente ha perdita zero. Il modello dei danni è proporzionale ai due fattori scelti.')
add('M15',1,'dipendenze','Dipendenze fra dati e risultati','Seguire l’effetto di una modifica al dato di ingresso.','Modifica una misura e osserva i risultati che devono essere rigenerati.','Il grafo delle dipendenze rende verificabile la provenienza di ogni risultato.',r'D\longrightarrow f(D)\longrightarrow g(f(D))',[num('value','Ultima misura',12,0,30,.5)],'''
x<-c(4,6,8,10,p$value);z<-(x-mean(x))/sd(x);data<-data.frame(indice=1:5,grezzo=x,standardizzato=z);plots<-list(point_plot(data,'indice','standardizzato','Risultato dipendente dai dati','Osservazione','Valore standardizzato'));metrics<-metric('Media di ingresso'=f(mean(x)),'SD di ingresso'=f(sd(x)),'Media standardizzata'=f(mean(z)),'Somma quadratica standardizzata'=f(sum(z^2)))
''')
add('M15',2,'tolleranze','Identità e confronto numerico','Scegliere una tolleranza coerente con la scala del problema.','Varia scala e perturbazione relativa; confronta scarto assoluto e relativo.','Una soglia numerica deve essere dichiarata insieme al criterio che la utilizza.',r'|a-b|\le\epsilon_{abs}+\epsilon_{rel}\max(|a|,|b|)',[num('scale','Ordine di grandezza: 10^k',6,0,12),num('relative','Perturbazione relativa × 10⁻⁸',2,0,10,.5)],'''
a<-10^p$scale;b<-a*(1+p$relative*1e-8);absd<-abs(a-b);reld<-absd/max(abs(a),abs(b));data<-data.frame(gruppo=c('Scarto assoluto','Scarto relativo'),valore=c(absd,reld));plots<-list(bar_plot(data,title='Scale del confronto numerico'));metrics<-metric('Scarto assoluto'=f(absd,8),'Scarto relativo'=f(reld,8),'Esito con εabs=10⁻⁶, εrel=10⁻⁸'=absd<=1e-6+1e-8*max(abs(a),abs(b)))
''')
add('M15',3,'contratti','Verificare una funzione prima dell’uso','Sottoporre una funzione a casi validi e invalidi.','Cambia il vettore dei pesi; verifica finitezza, segno e somma prima di calcolare la media pesata.','I controlli esplicitano il dominio della funzione e distinguono errori d’ingresso da risultati ammessi.',r'\bar x_w=\frac{\sum_iw_ix_i}{\sum_iw_i},\quad w_i\ge0,\quad\sum_iw_i>0',[choice('case','Caso di controllo',[('valid','Pesi validi'),('negative','Un peso negativo'),('zero','Tutti i pesi nulli')])],'''
x<-c(2,5,9);w<-switch(p$case,valid=c(1,2,1),negative=c(1,-2,1),zero=c(0,0,0));valid<-all(is.finite(w))&&all(w>=0)&&sum(w)>0;data<-data.frame(gruppo=c('A','B','C'),valore=w);plots<-list(bar_plot(data,title='Pesi sottoposti a controllo',yl='Peso'));metrics<-metric('Pesi non negativi'=all(w>=0),'Somma positiva'=sum(w)>0,'Risultato'=if(valid)f(weighted.mean(x,w))else'Input respinto dal contratto')
''')
add('M15',4,'casualita','Seme casuale e stato del generatore','Riprodurre una sequenza dichiarando il piano casuale.','Cambia il seme o il numero di estrazioni preliminari e confronta i risultati.','Il seme iniziale, l’algoritmo e l’ordine delle chiamate concorrono alla sequenza riproducibile.',r'X=G(s,\text{ordine delle chiamate})',[num('skip','Estrazioni preliminari',0,0,20)],'''
set.seed(p$seed);a<-rnorm(30);set.seed(p$seed);if(p$skip>0)invisible(rnorm(p$skip));b<-rnorm(30);data<-data.frame(x=1:30,y=a,secondo=b);plots<-list(line_plot(data,title='Sequenze con lo stesso seme',xl='Indice',yl='Valore')+geom_line(aes(y=secondo),colour=col_geo[2],linetype=2));metrics<-metric('Sequenze identiche'=identical(a,b),'Scarto massimo'=f(max(abs(a-b))),'Estrazioni preliminari'=p$skip)
''')
add('M15',5,'provenienza','Parametri, versioni e sensibilità','Confrontare risultati prodotti da scelte analitiche tracciate.','Modifica una soglia di filtro e osserva quali risultati cambiano nella nuova configurazione.','Una configurazione esportata conserva parametri, dati e codice necessari alla ricostruzione.',r'\widehat\theta=f(D;\eta,\mathcal V)',[num('cut','Soglia superiore della versione corrente',8,4,15,.5)],'''
x<-c(rnorm(60,5,1),10,12,14);cuts<-seq(4,15,.25);means<-sapply(cuts,function(c)mean(x[x<=c]));data<-data.frame(x=cuts,y=means);plots<-list(line_plot(data,title='Sensibilità della media alla soglia',xl='Soglia dichiarata',yl='Media dopo filtro')+geom_vline(xintercept=p$cut,linetype=2,colour=col_geo[2]));metrics<-metric('Soglia corrente'=p$cut,'Media corrente'=if(any(x<=p$cut))f(mean(x[x<=p$cut]))else'Nessuna osservazione ammessa','Osservazioni incluse'=sum(x<=p$cut))
''')
add('M16',1,'bersaglio','Bersaglio predittivo e nuove stazioni','Confrontare predizione di misure e trasferimento a nuove unità.','Aumenta l’effetto della stazione e confronta separazione casuale e separazione per gruppi.','Il protocollo di verifica deve corrispondere all’unità che sarà incontrata nell’uso futuro.',r'\widehat R=\frac1{n_{test}}\sum_i\mathbf1(\widehat y_i\ne y_i)',[num('station','Ampiezza dell’effetto di stazione',2,0,5,.5)],'''
g<-rep(1:12,each=12);u<-rnorm(12,0,p$station);x<-u[g]+rnorm(144,sd=.2);y<-as.integer(u[g]+rnorm(144,sd=.5)>0);data<-data.frame(x=x,y=y,stazione=g);random<-sample(1:144,96);group<-which(g<=8);score<-function(tr){te<-setdiff(1:144,tr);pred<-sapply(x[te],function(v)y[tr[which.min(abs(x[tr]-v))]]);mean(pred==y[te])};plots<-list(point_plot(data,title='Misure raggruppate per stazione',xl='Predittore',yl='Classe osservata'));metrics<-metric('Accuratezza separazione casuale'=f(score(random)),'Accuratezza nuove stazioni'=f(score(group)),'Stazioni complessive'=12)
''',limits='Classificatore a un vicino su un predittore sintetico. Le prestazioni variano con il campione; il vantaggio della separazione casuale non è imposto dal simulatore.')
add('M16',2,'geometria','Standardizzazione e confine decisionale','Esaminare un classificatore a centroidi nella metrica scelta.','Cambia scala e standardizzazione; osserva il confine di decisione.','La distanza utilizzata dal classificatore dipende dalla trasformazione stimata sul campione di addestramento.',r'\widehat c(x)=\arg\min_k\lVert T(x)-\mu_k\rVert^2',[num('scale','Moltiplicatore della seconda variabile',5,1,20),choice('standard','Standardizzazione',[('yes','Sì'),('no','No')])],'''
x<-rbind(cbind(rnorm(40,-1,1),rnorm(40,-.5,1)),cbind(rnorm(40,1,1),rnorm(40,.5,1)));y<-rep(0:1,each=40);x[,2]<-x[,2]*p$scale;center<-if(p$standard=='yes')colMeans(x)else c(0,0);sc<-if(p$standard=='yes')apply(x,2,sd)else c(1,1);z<-sweep(sweep(x,2,center),2,sc,'/');c0<-colMeans(z[y==0,]);c1<-colMeans(z[y==1,]);grid<-expand.grid(x=seq(min(x[,1])-1,max(x[,1])+1,length.out=45),y=seq(min(x[,2])-1,max(x[,2])+1,length.out=45));zg<-sweep(sweep(as.matrix(grid),2,center),2,sc,'/');grid$classe<-factor(as.integer(rowSums(sweep(zg,2,c1)^2)<rowSums(sweep(zg,2,c0)^2)));data<-data.frame(x=x[,1],y=x[,2],classe=factor(y));plots<-list(ggplot(grid,aes(x,y,fill=classe))+geom_raster(alpha=.25)+geom_point(data=data,aes(colour=classe),size=2)+scale_fill_manual(values=col_geo)+scale_colour_manual(values=col_geo)+labs(title='Centroidi e regioni decisionali',x='Variabile 1',y='Variabile 2'));metrics<-metric('Scala applicata a X2'=p$scale,'SD usata per X2'=f(sc[2]))
''')
add('M16',3,'selezione','Selezione dei predittori e contaminazione','Valutare la selezione di variabili su puro rumore.','Aumenta il numero dei candidati e confronta selezione sul training e selezione che usa anche il test.','La selezione informata dal test compromette l’indipendenza della valutazione.',r'j^*=\arg\max_j|\operatorname{cor}(X_j,Y)|',[num('features','Predittori candidati',100,10,500,10)],'''
x<-matrix(rnorm(120*p$features),nrow=120);y<-rbinom(120,1,.5);tr<-1:80;te<-81:120;jtrain<-which.max(abs(cor(x[tr,],y[tr])));jall<-which.max(abs(cor(x,y)));eval<-function(j){fit<-glm(y[tr]~x[tr,j],family=binomial());pr<-plogis(coef(fit)[1]+coef(fit)[2]*x[te,j]);mean((pr>=.5)==y[te])};ct<-as.numeric(cor(x[tr,],y[tr]));data<-data.frame(x=seq_along(ct),y=ct);plots<-list(point_plot(data,title='Associazioni candidate su rumore',xl='Predittore',yl='Correlazione nel training'));metrics<-metric('Accuratezza selezione sul training'=f(eval(jtrain)),'Accuratezza selezione contaminata'=f(eval(jall)),'Massima correlazione assoluta training'=f(max(abs(ct))))
''',limits='Le variabili sono indipendenti dal bersaglio. Il singolo campione può dare risultati di qualsiasi ordine; cambiare seme consente di osservare la variabilità della selezione.')
add('M16',4,'alberi','Alberi e aggregazione di classificatori','Confrontare un albero con un insieme di alberi su campioni bootstrap.','Varia profondità e numero di alberi; osserva probabilità e confini.','L’aggregazione media previsioni di modelli diversi; la profondità governa la complessità delle partizioni.',r'\widehat p_{bag}(x)=B^{-1}\sum_b\widehat p_b(x)',[num('depth','Profondità massima',2,1,4),num('trees','Alberi bootstrap',10,1,30)],'''
x<-matrix(runif(160,-2,2),ncol=2);y<-as.integer(x[,1]*x[,2]+rnorm(80,sd=.4)>0);grid<-expand.grid(x=seq(-2,2,length.out=30),y=seq(-2,2,length.out=30));pred<-replicate(p$trees,{idx<-sample(1:80,replace=TRUE);tree<-cart_fit(x[idx,],y[idx],depth=p$depth);cart_predict(tree,as.matrix(grid))});grid$z<-rowMeans(pred);data<-data.frame(x=x[,1],y=x[,2],classe=factor(y));plots<-list(map_plot(grid,title='Probabilità da alberi bootstrap',xl='Predittore 1',yl='Predittore 2')+geom_point(data=data,aes(x,y,shape=classe),inherit.aes=FALSE,colour='#142D3E',size=2));metrics<-metric('Alberi'=p$trees,'Profondità'=p$depth,'Probabilità media della griglia'=f(mean(grid$z)))
''',limits='CART didattico con divisioni assiali, criterio di Gini e almeno quattro casi per foglia; bagging senza sottocampionamento dei predittori. Non viene presentato come implementazione completa di random forest.')
add('M16',5,'metriche','Soglia, discriminazione e calibrazione','Separare probabilità previste e decisione binaria.','Cambia soglia e distorsione della calibrazione; confronta matrice di confusione e Brier score.','Una soglia modifica le decisioni, mentre la calibrazione riguarda il significato delle probabilità.',r'\operatorname{Brier}=n^{-1}\sum_i(p_i-y_i)^2',[num('threshold','Soglia decisionale',.5,.1,.9,.05),num('calibration','Moltiplicatore del logit',1,.25,3,.25)],'''
x<-rnorm(300);truth<-plogis(1.5*x);y<-rbinom(300,1,truth);pr<-plogis(p$calibration*1.5*x);decision<-pr>=p$threshold;tp<-sum(decision&y==1);fp<-sum(decision&y==0);tn<-sum(!decision&y==0);fn<-sum(!decision&y==1);bin<-cut(pr,seq(0,1,.1),include.lowest=TRUE);cal<-aggregate(cbind(pr,y)~bin,FUN=mean);data<-data.frame(probabilita=pr,osservato=y,decisione=decision);plots<-list(point_plot(cal,'pr','y','Calibrazione per intervalli di probabilità','Probabilità media prevista','Frequenza osservata')+geom_abline(intercept=0,slope=1,linetype=2)+coord_cartesian(xlim=c(0,1),ylim=c(0,1)));metrics<-metric('Veri positivi'=tp,'Falsi positivi'=fp,'Veri negativi'=tn,'Falsi negativi'=fn,'Sensibilità'=f(tp/(tp+fn)),'Specificità'=f(tn/(tn+fp)),'Brier score'=f(mean((pr-y)^2)))
''')
add('M16',6,'trasferimento','Trasferibilità e cambiamento della relazione','Valutare un modello su una popolazione differente.','Modifica la pendenza nel territorio di destinazione e osserva la perdita di calibrazione.','La validazione interna riguarda il dominio osservato; il trasferimento richiede una verifica coerente con il nuovo contesto.',r'P_{train}(Y\mid X)\quad\hbox{e}\quad P_{nuovo}(Y\mid X)',[num('slope','Pendenza nel nuovo territorio',1,-2,2,.25)],'''
x<-rnorm(200);y<-rbinom(200,1,plogis(x));fit<-glm(y~x,family=binomial());xt<-rnorm(300);yt<-rbinom(300,1,plogis(p$slope*xt));pr<-predict(fit,data.frame(x=xt),type='response');data<-data.frame(x=xt,y=pr,probabilita_nuova=plogis(p$slope*xt));data<-data[order(data$x),];plots<-list(line_plot(data,title='Modello trasferito e nuova relazione',xl='Predittore',yl='Probabilità')+geom_line(aes(y=probabilita_nuova),colour=col_geo[2],linetype=2));metrics<-metric('Accuratezza nuova popolazione'=f(mean((pr>=.5)==yt)),'Brier nuova popolazione'=f(mean((pr-yt)^2)),'Pendenza stimata nel training'=f(coef(fit)[2]))
''')
# Additional demonstrations cover distinct subtopics within the same course section.
add('M11',8,'kriging','Kriging ordinario e incertezza condizionata','Esaminare pesi e previsione di un campo con media costante e covarianza dichiarata.','Sposta la posizione di previsione e cambia la scala di correlazione.','La varianza di kriging è condizionata al modello di covarianza; la media costante è un’ipotesi del procedimento.',r'\begin{pmatrix}C&\mathbf1\\\mathbf1^\top&0\end{pmatrix}\begin{pmatrix}\lambda\\\nu\end{pmatrix}=\begin{pmatrix}c_0\\1\end{pmatrix},\quad\sigma_K^2=C(0)-\lambda^\top c_0-\nu',[num('range','Scala esponenziale [km]',2,.5,5,.5),num('x0','Est della previsione [km]',5,0,12,.5)],'''
xy<-cbind(runif(18,0,8),runif(18,0,8));dd<-as.matrix(dist(xy));C<-exp(-dd/p$range)+diag(1e-8,18);z<-as.vector(t(chol(C))%*%rnorm(18))+10;s0<-c(p$x0,4);c0<-exp(-sqrt(rowSums(sweep(xy,2,s0)^2))/p$range);K<-rbind(cbind(C,1),c(rep(1,18),0));sol<-solve(K,c(c0,1));w<-sol[1:18];pred<-sum(w*z);variance<-1-sum(w*c0)-sol[19];data<-data.frame(x=xy[,1],y=xy[,2],valore=z,peso=w);plots<-list(ggplot(data,aes(x,y,size=abs(peso),colour=valore))+geom_point()+scale_colour_gradientn(colours=col_geo[c(1,4,2)])+annotate('point',x=s0[1],y=s0[2],shape=4,size=6,stroke=1.5)+coord_equal()+labs(title='Siti, pesi assoluti e posizione da prevedere',x='Est [km]',y='Nord [km]'));metrics<-metric('Previsione'=f(pred),'Varianza kriging'=f(variance),'Somma pesi'=f(sum(w),8),'Pesi negativi'=sum(w<0))
''',limits='Campo gaussiano simulato con media costante e covarianza esponenziale isotropa di varianza unitaria. La scala è il parametro esponenziale, non un range finito. Termine diagonale 10⁻⁸ per stabilità numerica.')
add('M12',3,'allineamento','Allineamento e ricampionamento fra griglie','Valutare lo scarto introdotto da griglie con origine diversa.','Sposta una griglia e confronta assegnazione al vicino più prossimo e interpolazione bilineare.','La scelta del ricampionamento deve rispettare la natura continua o categoriale della variabile.',r'\widehat z(x,y)=\sum_{i,j\in\{0,1\}}w_{ij}(x,y)z_{ij}',[num('shift','Traslazione della griglia [celle]',.5,0,1,.1),choice('method','Metodo',[('nearest','Vicino più prossimo'),('bilinear','Bilineare')])],'''
fz<-function(x,y)sin(x/3)+cos(y/4);grid<-expand.grid(x=seq(1,18,.5)+p$shift,y=seq(1,18,.5)+p$shift);x0<-floor(grid$x);y0<-floor(grid$y);a<-grid$x-x0;b<-grid$y-y0;pr<-if(p$method=='nearest')fz(round(grid$x),round(grid$y))else(1-a)*(1-b)*fz(x0,y0)+a*(1-b)*fz(x0+1,y0)+(1-a)*b*fz(x0,y0+1)+a*b*fz(x0+1,y0+1);data<-grid;data$errore<-pr-fz(grid$x,grid$y);plots<-list(map_plot(data,'errore','Errore rispetto al campo continuo',xl='Colonna [indice]',yl='Riga [indice]'));metrics<-metric('RMSE ricampionamento'=f(sqrt(mean(data$errore^2))),'Scarto massimo'=f(max(abs(data$errore))))
''')
add('M05',8,'blocchi','Bootstrap a blocchi di una serie dipendente','Confrontare ricampionamento individuale e ricampionamento di sequenze temporali.','Aumenta la lunghezza dei blocchi conservando la medesima serie; confronta la dispersione delle medie ricampionate.','Il blocco conserva parte della dipendenza locale; la scelta della sua lunghezza contribuisce alla stima dell’incertezza.',r'B_s=(X_s,\ldots,X_{s+\ell-1}),\quad \bar X^*=n^{-1}\sum_i X_i^*',[num('length','Lunghezza dei blocchi',8,1,30),num('rho','Parametro AR(1)',.7,0,.9,.1),B()],'''
x<-ar_series(120,p$rho);n<-length(x);L<-p$length
individual<-replicate(p$B,mean(sample(x,replace=TRUE)))
blocks<-replicate(p$B,{start<-sample(1:n,ceiling(n/L),replace=TRUE);indices<-unlist(lapply(start,function(s)((s-1+0:(L-1))%%n)+1));mean(x[indices[1:n]])})
data<-data.frame(media=c(individual,blocks),metodo=rep(c('Singole osservazioni','Blocchi circolari'),each=p$B))
plots<-list(ggplot(data,aes(media,colour=metodo))+geom_density(linewidth=1.1)+scale_colour_manual(values=col_geo)+labs(title='Ricampionamento della stessa serie',x='Media bootstrap',y='Densità'))
metrics<-metric('SE osservazioni'=f(sd(individual)),'SE blocchi'=f(sd(blocks)),'Lunghezza del blocco'=L,'Osservazioni originali'=n)
''',limits='Serie AR(1) stazionaria di 120 osservazioni con varianza marginale unitaria. Bootstrap circolare: un blocco che supera il termine della serie riparte dall’inizio. La lunghezza del blocco è una scelta di sensibilità, non viene ottimizzata automaticamente.')
add('M06',9,'anova','Confrontare più medie','Valutare un’ipotesi globale su quattro gruppi con dispersioni controllate.','Modifica distanza fra le medie e rapporto delle deviazioni standard; confronta ANOVA classica e test globale di Welch.','Il rifiuto dell’ipotesi globale indica evidenza di almeno una differenza; l’identificazione dei contrasti richiede un’analisi successiva.',r'H_0:\mu_1=\cdots=\mu_G,\quad F=\frac{SS_{tra}/(G-1)}{SS_{entro}/(N-G)}',[num('delta','Incremento della media fra gruppi',.5,0,2,.25),num('ratio','Rapporto SD: ultimo / primo gruppo',2,1,4,.25),N(30)],'''
group<-factor(rep(LETTERS[1:4],each=p$n));mu<-rep((0:3)*p$delta,each=p$n);sigma<-rep(seq(1,p$ratio,length.out=4),each=p$n);y<-rnorm(4*p$n,mu,sigma)
data<-data.frame(gruppo=group,valore=y);classic<-anova(lm(y~group));welch<-oneway.test(y~group,var.equal=FALSE)
plots<-list(ggplot(data,aes(gruppo,valore,fill=gruppo))+geom_boxplot()+scale_fill_manual(values=col_geo)+labs(title='Quattro popolazioni gaussiane',x='Gruppo',y='Risposta'))
metrics<-metric('F classica'=f(classic$'F value'[1]),'p ANOVA classica'=f(classic$'Pr(>F)'[1]),'F Welch'=f(welch$statistic),'p Welch'=f(welch$p.value))
''',limits='Gruppi indipendenti gaussiani. Il test F classico assume varianze comuni; il test di Welch gestisce varianze differenti con un riferimento approssimato. Il campione è bilanciato.')
add('M15',2,'integrita','Integrità dei file e identità dei dati','Confrontare contenuto numerico, rappresentazione testuale e impronta di un file.','Modifica una misura prima dell’esportazione; verifica i byte dei due CSV e le rispettive impronte.','La ricostruzione conserva il file effettivamente analizzato e documenta quando il suo contenuto cambia.',r'D_A=D_B\Longrightarrow h(D_A)=h(D_B)',[num('delta','Variazione dell’ultima misura',0,0,1,.1)],'''
a<-data.frame(campione=1:5,valore=c(2,4,6,8,10));b<-a;b$valore[5]<-b$valore[5]+p$delta
fa<-tempfile(fileext='.csv');fb<-tempfile(fileext='.csv');write.csv(a,fa,row.names=FALSE);write.csv(b,fb,row.names=FALSE)
ha<-unname(tools::md5sum(fa));hb<-unname(tools::md5sum(fb));ba<-readBin(fa,'raw',n=file.info(fa)$size);bb<-readBin(fb,'raw',n=file.info(fb)$size)
data<-data.frame(x=1:5,y=a$valore,seconda_versione=b$valore)
plots<-list(point_plot(data,title='Due versioni dello stesso file',xl='Campione',yl='Valore')+geom_point(aes(y=seconda_versione),colour=col_geo[2],shape=4,size=4))
metrics<-metric('Byte identici'=identical(ba,bb),'Impronta A'=ha,'Impronta B'=hb,'Scarto numerico massimo'=max(abs(a$valore-b$valore)));unlink(c(fa,fb))
''',limits='Le impronte MD5 sono impiegate come controllo di integrità del flusso didattico. Il confronto byte per byte è esplicito; una coincidenza di hash non costituisce una dimostrazione matematica dell’identità dei file. I file temporanei vengono eliminati dopo il confronto.')

# Manifest and source generation; every section is accounted for, including supporting material.
def write_catalogue():
 ACT.sort(key=lambda a: (0 if a['module']=='T00' else int(a['module'][1:]),a['section']))
 seen=set()
 for a in ACT:
  assert a['id'] not in seen,a['id'];seen.add(a['id'])
  common=(ROOT/'R/lab-common.R').read_text()
  defaults={c['key']:c['value'] for c in a['controls']}
  def rval(v):return json.dumps(v,ensure_ascii=False) if isinstance(v,str) else str(v)
  rparams='p <- list('+', '.join(k+'='+rval(v) for k,v in defaults.items())+')'
  script='# '+a['title']+'\n# '+a['goal']+'\n# Dati sintetici. Parametri modificabili; esecuzione autonoma.\n# Dipendenze: install.packages(c("ggplot2", "jsonlite"))\n'+common+'\n'+rparams+'\nset.seed(p$seed)\n'+a['code']+'\nprint(metrics, row.names=FALSE)\nfor (g in plots) print(g)\n# write.csv(data, "dati_esperimento.csv", row.names=FALSE)\n# ggsave("figura.svg", plots[[1]], width=9, height=5.5)\n'
  (ROOT/a['source']).write_text(script)
 for prosefile in sorted((ROOT/'content').glob('prose-*.json')):
  for activity_id, fields in json.loads(prosefile.read_text()).items():
   for a in ACT:
    if a['id']==activity_id:a.update(fields)
 coverage=[]
 for f in sorted((ROOT/'moduli').glob('*/modulo.json')):
  m=json.loads(f.read_text());
  if m['id'].startswith('P'):continue
  for i,s in enumerate(m['sections'],1):
   ids=[a['id'] for a in ACT if a['module']==m['id'] and a['section']==i]
   # Opening, final exercises and references retain explicit links to the module's activities.
   role='esperimento' if ids else 'orientamento_esercizi_fonti'
   if not ids:ids=[a['id'] for a in ACT if a['module']==m['id']]
   coverage.append(dict(module=m['id'],section=i,title=s['title'],page=s['page'],role=role,activities=ids))
 assert all(a['limits'].strip() for a in ACT), 'Specific activity limits are required'
 assert len({a['limits'] for a in ACT})==len(ACT), 'Repeated activity limits'
 out=dict(version=json.loads((ROOT/'package.json').read_text())['version'],engine='R / webR 0.6.0',activities=ACT,coverage=coverage)
 (ROOT/'content/experiments.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
 (ROOT/'content/experiments-draft.json').write_text(json.dumps(ACT,ensure_ascii=False))
 print(len(ACT),'attività;',len(coverage),'sezioni inventariate;',sum(c['role']=='esperimento' for c in coverage),'sezioni con dimostrazioni dedicate')
if __name__=='__main__':
 write_catalogue()
 subprocess.run(['node','scripts/update-module-guides.mjs'],cwd=ROOT,check=True)
